ST.xhtml:
IF NOT VI_IsActivePLC THEN
    VO_Armed := FALSE;
    VO_Alarm_Active := FALSE;
    VO_Siren_Active := FALSE;
    VO_Send_Code_Req := FALSE;
    VO_Code_To_Send := '';
    VO_Status_Msg := 'Охрана: резервный ПЛК';
    L_Arming_In_Progress := FALSE;
    L_Disarm_Pending := FALSE;
    L_2FA_Required := FALSE;
    L_Reset_2FA := FALSE;
    RETURN;
END_IF;

// 1. Проверка PIN-кода или RFID-метки через менеджер кодов
fbAccessCode(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Code_To_Check := VI_PIN_Code,
    VI_RFID_To_Check := VI_RFID_Tag,
    VI_Access_Codes := GVL_RETAIN.G_Access_Codes,
    VI_RFID_Tags := GVL_RETAIN.G_RFID_Tags,
    VO_Code_Valid => L_Valid_PIN
);

// 2. Логика постановки на охрану (с задержкой на выход)
L_Auto_Arm_Trigger := FALSE;
IF VI_Config.auto_arm_enabled THEN
    IF VI_Current_TOD >= UDINT_TO_TOD(VI_Config.auto_arm_time_ms) THEN
        L_Auto_Arm_Trigger := TRUE;
    END_IF;
END_IF;
R_Trig_Auto_Arm(CLK := L_Auto_Arm_Trigger);

IF ((VI_Arm_Request AND L_Valid_PIN) OR R_Trig_Auto_Arm.Q) AND NOT VO_Armed AND NOT L_Arming_In_Progress THEN
    // Проверка, что все двери/окна закрыты перед постановкой (с учетом байпаса)
    L_Any_Sensor_Active := FALSE;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_DOOR_SENSORS DO IF VI_Door_Sensors[L_i] AND NOT VI_Bypass_Doors[L_i] THEN L_Any_Sensor_Active := TRUE; END_IF; END_FOR;
    FOR L_i := 1 TO 16 DO IF VI_Window_Sensors[L_i] AND NOT VI_Bypass_Windows[L_i] THEN L_Any_Sensor_Active := TRUE; END_IF; END_FOR;

    IF NOT L_Any_Sensor_Active THEN
        L_Arming_In_Progress := TRUE;
        VO_Status_Msg := 'Постановка на охрану. Покиньте помещение.';
    ELSE
        VO_Status_Msg := 'Ошибка постановки: Открыты двери или окна';
    END_IF;
END_IF;

L_Arm_Delay_Timer(IN := L_Arming_In_Progress, PT := TO_TIME(VI_Config.exit_delay_seconds * 1000), VI_System_Time_MS := VI_System_Time_MS);
IF L_Arm_Delay_Timer.Q THEN
    L_Arming_In_Progress := FALSE;
    VO_Armed := TRUE;
    VO_Status_Msg := 'Система под охраной';
END_IF;

// 3. Логика снятия с охраны с 2FA
IF VI_Disarm_Request AND L_Valid_PIN AND VO_Armed THEN
    IF VI_Config.enable_2fa THEN
        L_Disarm_Pending := TRUE;
        L_2FA_Required := TRUE;
        VO_Status_Msg := 'Ожидание 2FA для снятия с охраны';
    ELSE
        // Снятие без 2FA
        VO_Armed := FALSE;
        VO_Alarm_Active := FALSE;
        VO_Siren_Active := FALSE;
        L_Arming_In_Progress := FALSE;
        VO_Status_Msg := 'Система снята с охраны';
    END_IF;
END_IF;

fbTwoFactor(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Start_Auth := L_2FA_Required,
    VI_Method := E_TwoFactor_Method.TF_METHOD_TOTP, // Для примера
    VI_User_Code := VI_2FA_Code, // Используем отдельный вход для 2FA кода
    VI_Reset_Success := L_Reset_2FA
);

VO_Send_Code_Req := fbTwoFactor.VO_Send_Code_Req;
VO_Code_To_Send := fbTwoFactor.VO_Code_To_Send;

IF L_Disarm_Pending AND fbTwoFactor.VO_State.Is_Success THEN
    VO_Armed := FALSE;
    VO_Alarm_Active := FALSE;
    VO_Siren_Active := FALSE;
    L_Arming_In_Progress := FALSE;
    L_Disarm_Pending := FALSE;
    L_2FA_Required := FALSE;
    L_Reset_2FA := TRUE;
    VO_Status_Msg := 'Система снята с охраны';
ELSIF L_Disarm_Pending AND fbTwoFactor.VO_State.Is_Locked THEN
    L_Disarm_Pending := FALSE;
    L_2FA_Required := FALSE;
    L_Reset_2FA := FALSE;
    VO_Status_Msg := 'Ошибка 2FA: Превышено количество попыток';
ELSE
    L_Reset_2FA := FALSE;
END_IF;

// 4. Логика тревоги (с задержкой на вход)
IF VO_Armed THEN
    L_Any_Sensor_Active := FALSE;
    FOR L_i := 1 TO 16 DO IF VI_Motion_Sensors[L_i] AND NOT VI_Bypass_Motion[L_i] THEN L_Any_Sensor_Active := TRUE; END_IF; END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_DOOR_SENSORS DO IF VI_Door_Sensors[L_i] AND NOT VI_Bypass_Doors[L_i] THEN L_Any_Sensor_Active := TRUE; END_IF; END_FOR;
    FOR L_i := 1 TO 16 DO IF VI_Window_Sensors[L_i] AND NOT VI_Bypass_Windows[L_i] THEN L_Any_Sensor_Active := TRUE; END_IF; END_FOR;

    // Защелкиваем факт нарушения периметра, чтобы кратковременное срабатывание датчика не сбрасывало таймер
    IF L_Any_Sensor_Active THEN
        L_Alarm_Delay_Timer.IN := TRUE;
    END_IF;

    L_Alarm_Delay_Timer(PT := TO_TIME(VI_Config.entry_delay_seconds * 1000), VI_System_Time_MS := VI_System_Time_MS);

    IF L_Alarm_Delay_Timer.Q THEN
        VO_Alarm_Active := TRUE;
        VO_Siren_Active := TRUE;
        VO_Status_Msg := 'ТРЕВОГА! Нарушение периметра';
    ELSIF L_Alarm_Delay_Timer.IN THEN
        VO_Status_Msg := 'Внимание! Введите PIN-код для отмены тревоги';
    END_IF;
ELSE
    L_Alarm_Delay_Timer(IN := FALSE, PT := T#0s, VI_System_Time_MS := VI_System_Time_MS); // Сброс таймера при снятии с охраны
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Security_System_Manager <<<

// Check if command ID is already in history
L_Found := FALSE;
FOR L_i := 0 TO GVL_CONSTANTS.C_MAX_DEDUPLICATION_HISTORY-1 DO
    IF L_Processed_History[L_i] = VI_Command_ID AND VI_Command_ID <> 0 THEN
        // Check if the command is not too old (e.g., 1 hour = 3600000 ms)
        IF (VI_System_Time_MS - L_Processed_Times[L_i]) < 3600000 THEN
            L_Found := TRUE;
            EXIT;
        END_IF;
    END_IF;
END_FOR;

IF NOT L_Found AND VI_Command_ID <> 0 THEN
    // New command detected
    VO_Is_New_Command := TRUE;
    VO_Processed_ID := VI_Command_ID;

    // Add to history
    L_Processed_History[L_History_Index] := VI_Command_ID;
    L_Processed_Times[L_History_Index] := VI_System_Time_MS;
    L_History_Index := L_History_Index + 1;
    IF L_History_Index > GVL_CONSTANTS.C_MAX_DEDUPLICATION_HISTORY-1 THEN
        L_History_Index := 0;
    END_IF;
ELSE
    // Duplicate or empty command
    VO_Is_New_Command := FALSE;
    VO_Processed_ID := 0;
END_IF;

IF VI_Apply AND NOT L_Applied THEN
    // Простая калибровка смещением (одноточечная)
    VO_Offset := VI_Reference_Value - VI_Current_Value;
    VO_Done := TRUE;
    L_Applied := TRUE;
ELSIF NOT VI_Apply THEN
    VO_Done := FALSE;
    L_Applied := FALSE;
END_IF;

// Менеджер управления освещением и шторами/жалюзи.
// Обеспечивает работу по сценариями, датчикам движения, физическим выключателям и правилам.


IF NOT VI_IsActivePLC THEN RETURN; END_IF;


GVL_STATE.G_Lighting_IO_Fault := FALSE;
GVL_STATE.G_Lighting_Subsystem_Degraded := FALSE;

L_Effective_Scenario := VI_Current_Scenario;
L_Effective_Simulation_Active := VI_Simulation_Active;

CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        FOR L_j := 1 TO 32 DO
            VO_Lighting_Levels[L_j] := 0;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
            VO_Blinds_Positions[L_j] := 100;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_WET_ZONES DO
            VO_Wet_Zone_Light_Active[L_j] := FALSE;
        END_FOR;
        RETURN;
    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        L_Effective_Scenario := E_SCENARIO_TYPE.SCENARIO_NONE;
        L_Effective_Simulation_Active := FALSE;
    E_System_Operating_Mode.MODE_DEGRADED:
        L_Effective_Simulation_Active := FALSE;
END_CASE;

// Инициализация индекса мокрых зон
L_Wet_Zone_Idx := 1;
// Сброс массива мокрых зон
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_WET_ZONES DO
    VO_Wet_Zone_Light_Active[L_i] := FALSE;
END_FOR;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        GVL_STATE.G_Lighting_IO_Fault := TRUE;
GVL_STATE.G_Lighting_Subsystem_Degraded := TRUE;
        // Переход в безопасное состояние при потере связи (свет выкл, шторы открыты для эвакуации)
        FOR L_j := 1 TO 32 DO
            VO_Lighting_Levels[L_j] := 0;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
            VO_Blinds_Positions[L_j] := 100;
        END_FOR;
        RETURN;
    END_IF;
END_FOR;

// 1. Определение целевых уровней по сценарию (ТЗ 7.1)
IF L_Effective_Scenario >= 1 AND L_Effective_Scenario <= GVL_CONSTANTS.C_MAX_SCENARIOS THEN
    L_Target_Base_Light := VI_Scenario_Configs[L_Effective_Scenario].lighting_level_base;
    L_Target_Base_Blinds := VI_Scenario_Configs[L_Effective_Scenario].blinds_position_percent;
ELSE
    L_Target_Base_Light := 100;
    L_Target_Base_Blinds := 100;
END_IF;

// Корректировка по астрономическому таймеру
IF VI_Is_Night AND L_Effective_Scenario <> E_SCENARIO_TYPE.SCENARIO_AWAY AND L_Effective_Scenario <> E_SCENARIO_TYPE.SCENARIO_SLEEP THEN
    L_Target_Base_Blinds := 0; // Закрывать шторы ночью
END_IF;

// Плавный переход при смене сценария
IF L_Effective_Scenario <> L_Prev_Scenario THEN
    L_Transition_Light(
        VI_System_Time := VI_System_Time_MS,
        VI_Start_Time := VI_System_Time_MS,
        VI_Duration := 5000, // 5 секунд на плавное изменение света
        VI_Start_Value := TO_REAL(L_Base_Light),
        VI_End_Value := TO_REAL(L_Target_Base_Light)
    );
    L_Transition_Blinds(
        VI_System_Time := VI_System_Time_MS,
        VI_Start_Time := VI_System_Time_MS,
        VI_Duration := 10000, // 10 секунд на плавное изменение штор
        VI_Start_Value := TO_REAL(L_Base_Blinds),
        VI_End_Value := TO_REAL(L_Target_Base_Blinds)
    );
    L_Prev_Scenario := L_Effective_Scenario;
ELSE
    L_Transition_Light(
        VI_System_Time := VI_System_Time_MS,
        VI_Start_Time := L_Transition_Light.VI_Start_Time,
        VI_Duration := L_Transition_Light.VI_Duration,
        VI_Start_Value := L_Transition_Light.VI_Start_Value,
        VI_End_Value := TO_REAL(L_Target_Base_Light)
    );
    L_Transition_Blinds(
        VI_System_Time := VI_System_Time_MS,
        VI_Start_Time := L_Transition_Blinds.VI_Start_Time,
        VI_Duration := L_Transition_Blinds.VI_Duration,
        VI_Start_Value := L_Transition_Blinds.VI_Start_Value,
        VI_End_Value := TO_REAL(L_Target_Base_Blinds)
    );
END_IF;

L_Base_Light := TO_BYTE(L_Transition_Light.VO_Current_Value);
L_Base_Blinds := TO_BYTE(L_Transition_Blinds.VO_Current_Value);

// 2. Управление освещением
FOR L_i := 1 TO 32 DO
    L_Rule_Light_Active := FALSE;
    L_Rule_Light_Val := 0;

    // Проверка правил
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_LIGHTING_BASE THEN
                L_Rule_Light_Active := TRUE;
                L_Rule_Light_Val := REAL_TO_BYTE(VI_Rule_Actions[L_j].Value);
                L_Light_States[L_i] := (L_Rule_Light_Val > 0);
            ELSIF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_TOGGLE_LIGHTING AND VI_Rule_Actions[L_j].Triggered THEN
                L_Light_States[L_i] := NOT L_Light_States[L_i];
            END_IF;
        END_IF;
    END_FOR;

    // Приоритет 1: Физические выключатели (ТЗ 1.0)
    IF VI_Physical_Switches[L_i] AND NOT L_Prev_Switches[L_i] THEN
        L_Light_States[L_i] := NOT L_Light_States[L_i];
        L_Manual_Override[L_i] := TRUE; // Запоминаем ручное переопределение
    END_IF;
    L_Prev_Switches[L_i] := VI_Physical_Switches[L_i];

    // Приоритет 2: Датчики движения (ТЗ 2.0)
    // Защита от дребезга и удержание сигнала движения с помощью TOF
    L_Motion_Timers[L_i](IN := VI_Motion_Sensors[L_i], PT := T#5m, VI_System_Time_MS := VI_System_Time_MS);

    // Сброс ручного переопределения, когда комната становится пустой (задний фронт таймера движения)
    IF L_Prev_Motion_Q[L_i] AND NOT L_Motion_Timers[L_i].Q THEN
        L_Manual_Override[L_i] := FALSE;
    END_IF;
    L_Prev_Motion_Q[L_i] := L_Motion_Timers[L_i].Q;

    IF L_Motion_Timers[L_i].Q THEN
        IF NOT L_Manual_Override[L_i] THEN
            L_Light_States[L_i] := TRUE;
        END_IF;
    ELSE
        // Выключаем свет только если нет ручного переопределения
        IF NOT L_Manual_Override[L_i] THEN
            L_Light_States[L_i] := FALSE;
        END_IF;
    END_IF;

    // Приоритет 3: Симуляция (только в режиме Away)
    IF L_Effective_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY AND L_Effective_Simulation_Active THEN
        L_Light_States[L_i] := VI_Simulation_Lights[L_i];
    END_IF;

    // Приоритет 4: Ручное управление и правила
    IF VI_Manual_Light_Override[L_i] > 0 THEN
        VO_Lighting_Levels[L_i] := VI_Manual_Light_Override[L_i];
    ELSIF L_Rule_Light_Active THEN
        VO_Lighting_Levels[L_i] := L_Rule_Light_Val;
    ELSE
        VO_Lighting_Levels[L_i] := SEL(L_Light_States[L_i], 0, L_Base_Light);
    END_IF;

    // 5. Мокрые зоны
    IF VI_Wet_Zone_Map[L_i] AND L_Wet_Zone_Idx <= GVL_CONSTANTS.C_MAX_WET_ZONES THEN
        VO_Wet_Zone_Light_Active[L_Wet_Zone_Idx] := (VO_Lighting_Levels[L_i] > 10);
        L_Wet_Zone_Idx := L_Wet_Zone_Idx + 1;
    END_IF;
END_FOR;

// 3. Управление шторами
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
    L_Rule_Blinds_Active := FALSE;
    L_Rule_Blinds_Val := 0;

    // Проверка правил
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_BLINDS THEN
                L_Rule_Blinds_Active := TRUE;
                L_Rule_Blinds_Val := REAL_TO_BYTE(VI_Rule_Actions[L_j].Value);
            END_IF;
        END_IF;
    END_FOR;

    // Приоритет 1: Ручное управление
    IF VI_Manual_Blinds_Override[L_i] > 0 THEN
        VO_Blinds_Positions[L_i] := VI_Manual_Blinds_Override[L_i];
    // Приоритет 2: Правила
    ELSIF L_Rule_Blinds_Active THEN
        VO_Blinds_Positions[L_i] := L_Rule_Blinds_Val;
    // Приоритет 3: Сценарий
    ELSE
        VO_Blinds_Positions[L_i] := L_Base_Blinds;
    END_IF;
END_FOR;

// >>> BULK_SYNC_ANCHOR: FB_Lighting_Blinds_Manager <<<

// 1. Prepare K_ipad and K_opad
FOR i := 0 TO 63 DO
    IF i < KeyLength THEN
        K_ipad[i] := Key[i] XOR 16#36;
        K_opad[i] := Key[i] XOR 16#5C;
    ELSE
        K_ipad[i] := 16#36;
        K_opad[i] := 16#5C;
    END_IF;
END_FOR;

// 2. Inner Hash: SHA1(K_ipad || Message)
FOR i := 0 TO 63 DO
    InnerData[i] := K_ipad[i];
END_FOR;
FOR i := 0 TO MessageLength - 1 DO
    InnerData[64 + i] := Message[i];
END_FOR;

FB_SHA1_Inner(Data := InnerData, Length := 64 + MessageLength, Hash => InnerHash);

// 3. Outer Hash: SHA1(K_opad || InnerHash)
FOR i := 0 TO 63 DO
    OuterData[i] := K_opad[i];
END_FOR;
FOR i := 0 TO 19 DO
    OuterData[64 + i] := InnerHash[i];
END_FOR;

FB_SHA1_Outer(Data := OuterData, Length := 84, Hash => Hash);

Done := TRUE;

GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Event_ID := GVL_EVENT.G_Event_ID_Counter;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Event_Type := VI_Event_Type;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Timestamp := VI_Timestamp;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Param1 := VI_Param1;
GVL_EVENT.G_Event_Log[GVL_EVENT.G_Event_Head].Param2 := VI_Param2;

GVL_EVENT.G_Event_ID_Counter := GVL_EVENT.G_Event_ID_Counter + 1;
GVL_EVENT.G_Event_Head := (GVL_EVENT.G_Event_Head + 1) MOD 64;

L_Event_Text := '';

IF (VI_Severity <> L_Last_Severity) OR (VI_RootCause <> L_Last_RootCause) THEN
    CASE VI_RootCause OF
        E_System_Root_Cause.ROOT_FIRE:
            L_Event_Text := 'EVENT: FIRE DETECTED';
        E_System_Root_Cause.ROOT_GAS_LEAK:
            L_Event_Text := 'EVENT: GAS LEAK';
        E_System_Root_Cause.ROOT_CO_CRITICAL:
            L_Event_Text := 'EVENT: CO CRITICAL';
        E_System_Root_Cause.ROOT_CO_WARNING:
            L_Event_Text := 'EVENT: CO WARNING';
        E_System_Root_Cause.ROOT_WATER_LEAK:
            L_Event_Text := 'EVENT: WATER LEAK';
        E_System_Root_Cause.ROOT_SENSOR_FAULT:
            L_Event_Text := 'EVENT: SENSOR FAULT';
        E_System_Root_Cause.ROOT_IO_OFFLINE:
            L_Event_Text := 'EVENT: IO OFFLINE';
        E_System_Root_Cause.ROOT_COMM_FAULT:
            L_Event_Text := 'EVENT: COMM FAULT';
        E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
            L_Event_Text := 'EVENT: WATCHDOG FAULT';
        E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT:
            L_Event_Text := 'EVENT: SUBSYSTEM FAULT';
        ELSE
            L_Event_Text := 'EVENT: SYSTEM STATE CHANGE';
    END_CASE;

    L_Write_Index := L_Write_Index + 1;
    IF L_Write_Index > 16 THEN
        L_Write_Index := 1;
    END_IF;

    VO_Event_Time_MS[L_Write_Index] := VI_Time_MS;
    VO_Event_Severity[L_Write_Index] := VI_Severity;
    VO_Event_RootCause[L_Write_Index] := VI_RootCause;
    VO_Event_Text[L_Write_Index] := L_Event_Text;

    VO_Last_Index := L_Write_Index;
    VO_Last_Event_Text := L_Event_Text;

    IF VO_Event_Count < 16 THEN
        VO_Event_Count := VO_Event_Count + 1;
    END_IF;
END_IF;

L_Last_Severity := VI_Severity;
L_Last_RootCause := VI_RootCause;
// >>> BULK_SYNC_ANCHOR: FB_Fault_Logger <<<

VO_Overheat_Detected := FALSE;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VI_Temps[L_i] > VI_Threshold THEN
        VO_Overheat_Detected := TRUE;
        VO_Locked_Circuits[L_i] := TRUE;
    END_IF;
END_FOR;

VO_HMI_Status_Text := VI_Status_Msg;

CASE VI_Severity OF
    E_System_Severity.SEV_NORMAL:
        VO_HMI_State_Code := 0;
    E_System_Severity.SEV_WARNING:
        VO_HMI_State_Code := 1;
    E_System_Severity.SEV_DEGRADED:
        VO_HMI_State_Code := 2;
    E_System_Severity.SEV_CRITICAL:
        VO_HMI_State_Code := 3;
END_CASE;
// >>> BULK_SYNC_ANCHOR: FB_HMI_Interface <<<

// Debounce non-critical diagnostics: require 3 stable cycles to assert/clear
IF VI_IO_Offline THEN
    L_IO_Fault_Clear_Count := 0;
    IF L_IO_Fault_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Assert_Count := L_IO_Fault_Assert_Count + 1;
    END_IF;
    IF L_IO_Fault_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_IO_Fault_Assert_Count := 0;
    IF L_IO_Fault_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Clear_Count := L_IO_Fault_Clear_Count + 1;
    END_IF;
    IF L_IO_Fault_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_IO_Fault_Stable := FALSE;
    END_IF;
END_IF;

IF VI_Comm_Fault THEN
    L_Comm_Fault_Clear_Count := 0;
    IF L_Comm_Fault_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Assert_Count := L_Comm_Fault_Assert_Count + 1;
    END_IF;
    IF L_Comm_Fault_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_Comm_Fault_Assert_Count := 0;
    IF L_Comm_Fault_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Clear_Count := L_Comm_Fault_Clear_Count + 1;
    END_IF;
    IF L_Comm_Fault_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Comm_Fault_Stable := FALSE;
    END_IF;
END_IF;

IF VI_Sensor_Fault THEN
    L_Sensor_Fault_Clear_Count := 0;
    IF L_Sensor_Fault_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Assert_Count := L_Sensor_Fault_Assert_Count + 1;
    END_IF;
    IF L_Sensor_Fault_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_Sensor_Fault_Assert_Count := 0;
    IF L_Sensor_Fault_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Clear_Count := L_Sensor_Fault_Clear_Count + 1;
    END_IF;
    IF L_Sensor_Fault_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Sensor_Fault_Stable := FALSE;
    END_IF;
END_IF;

IF VI_Subsystem_Fault THEN
    L_Subsystem_Clear_Count := 0;
    IF L_Subsystem_Assert_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Assert_Count := L_Subsystem_Assert_Count + 1;
    END_IF;
    IF L_Subsystem_Assert_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Fault_Stable := TRUE;
    END_IF;
ELSE
    L_Subsystem_Assert_Count := 0;
    IF L_Subsystem_Clear_Count < C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Clear_Count := L_Subsystem_Clear_Count + 1;
    END_IF;
    IF L_Subsystem_Clear_Count >= C_HEALTH_DEBOUNCE_CYCLES THEN
        L_Subsystem_Fault_Stable := FALSE;
    END_IF;
END_IF;

// Count confirmed fault events on rising edge of stable/critical conditions
IF L_IO_Fault_Stable AND NOT L_IO_Fault_Prev THEN
    VO_IO_Fault_Count := VO_IO_Fault_Count + 1;
END_IF;
L_IO_Fault_Prev := L_IO_Fault_Stable;

IF L_Comm_Fault_Stable AND NOT L_Comm_Fault_Prev THEN
    VO_Comm_Fault_Count := VO_Comm_Fault_Count + 1;
END_IF;
L_Comm_Fault_Prev := L_Comm_Fault_Stable;

IF L_Sensor_Fault_Stable AND NOT L_Sensor_Fault_Prev THEN
    VO_Sensor_Fault_Count := VO_Sensor_Fault_Count + 1;
END_IF;
L_Sensor_Fault_Prev := L_Sensor_Fault_Stable;

IF L_Subsystem_Fault_Stable AND NOT L_Subsystem_Fault_Prev THEN
    VO_Subsystem_Fault_Count := VO_Subsystem_Fault_Count + 1;
END_IF;
L_Subsystem_Fault_Prev := L_Subsystem_Fault_Stable;

IF VI_Watchdog_Fault AND NOT L_Watchdog_Fault_Prev THEN
    VO_Watchdog_Fault_Count := VO_Watchdog_Fault_Count + 1;
END_IF;
L_Watchdog_Fault_Prev := VI_Watchdog_Fault;

VO_Sensor_Fault := L_Sensor_Fault_Stable;
VO_IO_Fault := L_IO_Fault_Stable;
VO_Comm_Fault := L_Comm_Fault_Stable;
VO_Subsystem_Degraded := L_Subsystem_Fault_Stable;

VO_System_Severity := E_System_Severity.SEV_NORMAL;
VO_Root_Cause := E_System_Root_Cause.ROOT_NONE;
VO_First_Fault_Active := FALSE;
VO_First_Fault_Type := 0;
VO_First_Fault_Source := 0;

// Priority: FIRE > GAS > CO > WATER > diagnostics
IF VI_Smoke_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_FIRE;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 5;

ELSIF VI_Gas_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_GAS_LEAK;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 6;

ELSIF VI_CO_Alarm_Level THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_CO_CRITICAL;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 7;

ELSIF VI_CO_Warning_Level THEN
    VO_System_Severity := E_System_Severity.SEV_WARNING;
    VO_Root_Cause := E_System_Root_Cause.ROOT_CO_WARNING;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 7;

ELSIF VI_Leak_Detected THEN
    VO_System_Severity := E_System_Severity.SEV_WARNING;
    VO_Root_Cause := E_System_Root_Cause.ROOT_WATER_LEAK;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 8;

ELSIF VI_Watchdog_Fault THEN
    VO_System_Severity := E_System_Severity.SEV_CRITICAL;
    VO_Root_Cause := E_System_Root_Cause.ROOT_WATCHDOG_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 9;

ELSIF L_IO_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_IO_OFFLINE;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 1;

ELSIF L_Comm_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_COMM_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 3;

ELSIF L_Sensor_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_SENSOR_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 2;

ELSIF L_Subsystem_Fault_Stable THEN
    VO_System_Severity := E_System_Severity.SEV_DEGRADED;
    VO_Root_Cause := E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT;
    VO_First_Fault_Active := TRUE;
    VO_First_Fault_Type := 4;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_System_Health <<<

// Упрощенная модель износа
IF VI_Nominal_Life > 0 THEN
    VO_Remaining_Percent := TO_BYTE(100 - (VI_Runtime_Hours * 100 / VI_Nominal_Life));
ELSE
    VO_Remaining_Percent := 0;
END_IF;

VO_Maintenance_Req := (VO_Remaining_Percent < 10);

// === SERIALIZE PERSIST STRUCT → BUFFER ===

// System Mode
VIO_Persist_Buffer[0] := TO_BYTE(TO_INT(VI_PersistStruct.System_Mode));

// Gas
IF VI_PersistStruct.Safety_Gas_Latched THEN
    VIO_Persist_Buffer[1] := BYTE#1;
ELSE
    VIO_Persist_Buffer[1] := BYTE#0;
END_IF;

// Smoke
IF VI_PersistStruct.Safety_Smoke_Latched THEN
    VIO_Persist_Buffer[2] := BYTE#1;
ELSE
    VIO_Persist_Buffer[2] := BYTE#0;
END_IF;

// Leak
IF VI_PersistStruct.Safety_Leak_Latched THEN
    VIO_Persist_Buffer[3] := BYTE#1;
ELSE
    VIO_Persist_Buffer[3] := BYTE#0;
END_IF;

// DHW Pump
IF VI_PersistStruct.DHW_Heating_Pump THEN
    VIO_Persist_Buffer[4] := BYTE#1;
ELSE
    VIO_Persist_Buffer[4] := BYTE#0;
END_IF;

// === END SERIALIZE ===

L_Persist_Buffer_Changed :=
    (VIO_Persist_Buffer[0] <> VIO_Last_Written_Persist_Buffer[0]) OR
    (VIO_Persist_Buffer[1] <> VIO_Last_Written_Persist_Buffer[1]) OR
    (VIO_Persist_Buffer[2] <> VIO_Last_Written_Persist_Buffer[2]) OR
    (VIO_Persist_Buffer[3] <> VIO_Last_Written_Persist_Buffer[3]) OR
    (VIO_Persist_Buffer[4] <> VIO_Last_Written_Persist_Buffer[4]);

VO_NVRAM_Cmd := 0;
VO_NVRAM_Offset := 0;

IF VIO_Apply_Settings THEN
    // explicit config apply requests a controlled write
    // keep flag set until successful write confirmation
    VO_NVRAM_Cmd := 1;

ELSIF L_Persist_Buffer_Changed THEN
    // controlled write: no more often than once per 60 seconds
    IF (VIO_Last_Persist_Write_MS = 0) OR
       ((VI_System_Time_MS - VIO_Last_Persist_Write_MS) >= 60000) THEN
        VO_NVRAM_Cmd := 1;
    END_IF;
END_IF;

fbNVRAMManager(
    VI_Command := VO_NVRAM_Cmd,
    VI_Offset := VO_NVRAM_Offset,
    VI_DataRef := VIO_Persist_Buffer[0],
    VI_DataSize := 5,
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Operator_ID := 'SYSTEM',
    VI_IsActivePLC := VI_IsActivePLC,
    VI_TwoPersonConfirmation := FALSE,
    VO_Done => VO_NVRAM_Done,
    VO_Error => VO_NVRAM_Err,
    VO_ErrorID => VO_NVRAM_ErrID
);

IF (VO_NVRAM_Cmd = 1) AND VO_NVRAM_Done AND NOT VO_NVRAM_Err THEN
    VIO_Last_Written_Persist_Buffer[0] := VIO_Persist_Buffer[0];
    VIO_Last_Written_Persist_Buffer[1] := VIO_Persist_Buffer[1];
    VIO_Last_Written_Persist_Buffer[2] := VIO_Persist_Buffer[2];
    VIO_Last_Written_Persist_Buffer[3] := VIO_Persist_Buffer[3];
    VIO_Last_Written_Persist_Buffer[4] := VIO_Persist_Buffer[4];
    VIO_Last_Persist_Write_MS := VI_System_Time_MS;
    VIO_Apply_Settings := FALSE;
END_IF;

// Normalize count to analyzer bounds
L_Count := UDINT_TO_INT(VI_Data.record_count);
IF L_Count < 0 THEN
    L_Count := 0;
END_IF;
IF L_Count > GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS THEN
    L_Count := GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS;
END_IF;

// Copy source values into analyzer-compatible buffer
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS DO
    L_Data_Copy[L_i] := 0.0;
END_FOR;

IF L_Count > 0 THEN
    FOR L_i := 1 TO L_Count DO
        L_Data_Copy[L_i] := VI_Data.values[L_i];
    END_FOR;
END_IF;

fbAnalyzer(
    VI_Count := L_Count,
    VI_Data := L_Data_Copy,
    VO_Average => VO_Average,
    VO_Max => VO_Max,
    VO_Min => VO_Min,
    VO_Trend_Up => VO_Trend_Up,
    VO_Trend_Down => VO_Trend_Down
);

// Если ПЛК находится в режиме Standby (резерв), он не должен управлять выходами
IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

IF VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    VO_Gate_Open := FALSE;
    VO_Wicket_Open := FALSE;
    VO_Lock_1_Open := FALSE;
    VO_Lock_2_Open := FALSE;
    RETURN;
END_IF;

// 1. Логика автоматического закрытия замков при постановке на охрану (ТЗ 3.0)
// При переходе системы в режим "Охрана" принудительно блокируем все замки
IF VI_Armed AND NOT L_Prev_Armed THEN
    L_Auto_Lock_Req := TRUE;
END_IF;
L_Prev_Armed := VI_Armed;

// Детекторы фронта для команд
R_Trig_Gate(CLK := VI_Gate_Open_Req);
R_Trig_Wicket(CLK := VI_Wicket_Open_Req);
R_Trig_Lock_1_O(CLK := VI_Lock_1_Open_Req);
R_Trig_Lock_1_C(CLK := VI_Lock_1_Close_Req OR L_Auto_Lock_Req);
R_Trig_Lock_2_O(CLK := VI_Lock_2_Open_Req);
R_Trig_Lock_2_C(CLK := VI_Lock_2_Close_Req OR L_Auto_Lock_Req);

// Проверка PIN-кода или RFID-метки через менеджер кодов
fbAccessCode(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Code_To_Check := VI_PIN_Code,
    VI_RFID_To_Check := VI_RFID_Tag,
    VI_Access_Codes := VI_Access_Codes,
    VI_RFID_Tags := VI_RFID_Tags,
    VO_Code_Valid => L_Valid_PIN
);

// 2. Формирование импульсов управления исполнительными механизмами (Pulse Control)
// Открытие ворот и калитки требует валидного ПИН-кода или RFID-метки, если система под охраной
L_Gate_Timer(IN := R_Trig_Gate.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.gate_open_pulse_ms));
VO_Gate_Open := L_Gate_Timer.Q;

L_Wicket_Timer(IN := R_Trig_Wicket.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.wicket_open_pulse_ms));
VO_Wicket_Open := L_Wicket_Timer.Q;

L_Lock_1_Open_T(IN := R_Trig_Lock_1_O.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.lock_open_pulse_ms));
VO_Lock_1_Open := L_Lock_1_Open_T.Q;

L_Lock_1_Close_T(IN := R_Trig_Lock_1_C.Q, PT := TO_TIME(VI_Config.lock_close_pulse_ms));
VO_Lock_1_Close := L_Lock_1_Close_T.Q;

L_Lock_2_Open_T(IN := R_Trig_Lock_2_O.Q AND (NOT VI_Armed OR L_Valid_PIN), PT := TO_TIME(VI_Config.lock_open_pulse_ms));
VO_Lock_2_Open := L_Lock_2_Open_T.Q;

L_Lock_2_Close_T(IN := R_Trig_Lock_2_C.Q, PT := TO_TIME(VI_Config.lock_close_pulse_ms));
VO_Lock_2_Close := L_Lock_2_Close_T.Q;

// Сброс флага автоматического закрытия
IF L_Auto_Lock_Req THEN
    L_Auto_Lock_Req := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Access_Control <<<

IF NOT VI_Config.enabled THEN RETURN; END_IF;

// Логирование по изменению (Deadband) или по времени (раз в час)
L_Deviation := ABS(VI_Current_Value - L_Last_Value);
IF (L_Deviation >= (L_Last_Value * VI_Config.deviation_threshold_percent / 100.0)) OR 
   ((SEL(VI_System_Time_MS >= L_Last_Log_Time, VI_System_Time_MS - L_Last_Log_Time, (4294967295 - L_Last_Log_Time) + VI_System_Time_MS + 1)) >= GVL_CONSTANTS.C_MS_IN_HOUR) THEN

    // Запись в массив
    VO_Data.write_index := (VO_Data.record_count MOD 100) + 1;
    VO_Data.values[VO_Data.write_index] := VI_Current_Value;
    VO_Data.timestamps[VO_Data.write_index] := VI_System_Time_MS;

    VO_Data.record_count := VO_Data.record_count + 1;
    VO_Data.sum_values := VO_Data.sum_values + VI_Current_Value;

    L_Last_Value := VI_Current_Value;
    L_Last_Log_Time := VI_System_Time_MS;
END_IF;

// ==============================================================================
// Блок таймера, привязанный к системному времени (System Timer)
// Назначение:
// - Замена стандартного TON для обеспечения точной выдержки времени,
//   независимой от времени цикла ПЛК, с использованием единого системного времени.
// ==============================================================================



IF IN THEN
    IF NOT L_Running THEN
        L_Start_Time := VI_System_Time_MS;
        L_Running := TRUE;
        ET := T#0s;
        Q := FALSE;
    ELSE
        // Обработка переполнения UDINT (примерно 49 дней)
        ET := TO_TIME((SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1)));

        IF ET >= PT THEN
            Q := TRUE;
            ET := PT;
        ELSE
            Q := FALSE;
        END_IF;
    END_IF;
ELSE
    L_Running := FALSE;
    ET := T#0s;
    Q := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_System_Timer <<<

// Детекция фронта команды
L_cmd_rising := (VI_Command <> 0) AND (L_prev_Command = 0);
L_prev_Command := VI_Command;

IF L_cmd_rising THEN
    VO_Done := FALSE;
    VO_Error := FALSE;
    VO_ErrorID := 0;
    VO_HMI_Status_Message := '';

    // Валидация смещения
    IF VI_Offset >= C_MAX_NVRAM_SIZE THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#1501;
        VO_HMI_Status_Message := 'NVRAM: Неверное смещение';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    // Валидация указателя
    IF NOT __ISVALIDREF(VI_DataRef) THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#150A;
        VO_HMI_Status_Message := 'NVRAM: Недействительная ссылка на данные';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    L_pData := ADR(VI_DataRef);

    IF (VI_Offset + VI_DataSize) > C_MAX_NVRAM_SIZE THEN
        VO_Error := TRUE;
        VO_ErrorID := 16#150B;
        VO_HMI_Status_Message := 'NVRAM: Размер данных превышает доступный объем';
        VO_Done := TRUE;
        RETURN;
    END_IF;

    IF VI_Command = 2 THEN
    VO_Error := TRUE;
    VO_ErrorID := 16#150D;
    VO_HMI_Status_Message := 'NVRAM: READ not implemented';
    VO_Done := TRUE;
    RETURN;
END_IF;

IF VI_Command = 1 THEN // ЗАПИСЬ (WRITE)
        IF NOT VI_IsActivePLC THEN
            VO_Error := TRUE;
            VO_ErrorID := 16#1509;
            VO_HMI_Status_Message := 'NVRAM: Запись запрещена (STANDBY)';
        ELSE
            // Проверка на изменение данных перед записью
            L_Data_Changed := FALSE;
            FOR L_i := 0 TO VI_DataSize - 1 DO
                IF GVL_Retain.G_NVRAM_Data[VI_Offset + L_i] <> L_pData[L_i] THEN
                    L_Data_Changed := TRUE;
                    EXIT;
                END_IF;
            END_FOR;

            IF L_Data_Changed THEN
                // Безопасное копирование (WRITE)
                FOR L_i := 0 TO VI_DataSize - 1 DO
                    GVL_Retain.G_NVRAM_Data[VI_Offset + L_i] := L_pData[L_i];
                END_FOR;
                VO_HMI_Status_Message := 'NVRAM: Данные успешно сохранены в RETAIN';
            ELSE
                VO_HMI_Status_Message := 'NVRAM: Данные не изменились, запись пропущена';
            END_IF;
        END_IF;
        VO_Done := TRUE;
    END_IF;
END_IF;

IF VI_Command = 0 THEN
    VO_Done := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_NVRAM_Manager <<<

IF VI_Write_Event AND NOT L_Prev_Write_Event THEN
    GVL_Retain.G_History_Buffer[GVL_Retain.G_History_Write_Idx] := VI_Event;
    GVL_Retain.G_History_Buffer[GVL_Retain.G_History_Write_Idx].timestamp_ms := VI_System_Time_MS;

    GVL_Retain.G_History_Write_Idx := (GVL_Retain.G_History_Write_Idx MOD GVL_CONSTANTS.C_MAX_HISTORY_RECORDS) + 1;
    GVL_Retain.G_History_Total_Events := GVL_Retain.G_History_Total_Events + 1;
END_IF;
L_Prev_Write_Event := VI_Write_Event;

VO_Total_Events := GVL_Retain.G_History_Total_Events;
// >>> BULK_SYNC_ANCHOR: FB_History_Manager <<<

// Менеджер управления розетками.
// Обеспечивает работу по сценариям, правилам и аварийное отключение (без локальных выключателей розеток).


IF NOT VI_IsActivePLC THEN RETURN; END_IF;


// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        // Переход в безопасное состояние при потере связи (отключение всех розеток)
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
            VO_Socket_States[L_j] := FALSE;
        END_FOR;
        RETURN;
    END_IF;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SOCKETS DO
    L_Rule_Active := FALSE;
    L_Rule_State := FALSE;

    L_Manual_Trig[L_i](CLK := VI_Manual_Override[L_i]);

    // Ручное переключение
    IF L_Manual_Trig[L_i].Q THEN
        L_Internal_State[L_i] := NOT L_Internal_State[L_i];
    END_IF;

    // Проверка правил для текущей розетки
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_SOCKET THEN
                L_Rule_Active := TRUE;
                L_Rule_State := (VI_Rule_Actions[L_j].Value > 0.5);
                L_Internal_State[L_i] := L_Rule_State; // Синхронизация внутреннего состояния
            ELSIF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_TOGGLE_SOCKET AND VI_Rule_Actions[L_j].Triggered THEN
                L_Internal_State[L_i] := NOT L_Internal_State[L_i]; // Toggle
            END_IF;
        END_IF;
    END_FOR;

    // Аварийное отключение
    IF VI_Fire_Alarm OR VI_Flood_Alarm THEN
        // Розетки 1-4 неотключаемые (холодильник, сервер и т.д.)
        IF L_i > 4 THEN
            VO_Socket_States[L_i] := FALSE;
        ELSE
            // Критические розетки сохраняют свое текущее внутреннее состояние, а не форсируются в TRUE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    ELSIF VI_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY OR VI_Security_Armed THEN
        // Master Off
        IF L_i > 4 THEN
            VO_Socket_States[L_i] := FALSE;
        ELSE
            // Неотключаемые розетки могут управляться вручную
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    ELSE
        // Нормальный режим: состояние определяется внутренним состоянием (ручным или правилом)
        IF L_Rule_Active THEN
            VO_Socket_States[L_i] := L_Rule_State;
        ELSE
            VO_Socket_States[L_i] := L_Internal_State[L_i];
        END_IF;
    END_IF;
END_FOR;

VO_Internal_States := L_Internal_State;

// >>> BULK_SYNC_ANCHOR: FB_Socket_Manager <<<

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

// Reset outputs
VO_Smoke_Detected := FALSE;
VO_Gas_Detected := FALSE;
VO_CO_Warning_Level := FALSE;
VO_CO_Alarm_Level := FALSE;
VO_Status_Msg := 'ОК';

// --- Methane ---
L_Methane_Max := 0.0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO
    IF VI_Methane_LEL[L_i] > L_Methane_Max THEN
        L_Methane_Max := VI_Methane_LEL[L_i];
    END_IF;
END_FOR;

IF L_Methane_Max >= 20.0 THEN
    VO_Gas_Detected := TRUE;
END_IF;

// --- CO ---
L_CO_Max := 0.0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_CO_SENSORS DO
    IF VI_CO_PPM[L_i] > L_CO_Max THEN
        L_CO_Max := VI_CO_PPM[L_i];
    END_IF;
END_FOR;

L_CO_Level_30 := (L_CO_Max >= 30.0);
L_CO_Level_70 := (L_CO_Max >= 70.0);
L_CO_Level_400 := (L_CO_Max >= 400.0);

L_CO_Timer_30ppm(IN := L_CO_Level_30, PT := T#8h, VI_System_Time_MS := VI_System_Time_MS);
L_CO_Timer_70ppm(IN := L_CO_Level_70, PT := T#1h, VI_System_Time_MS := VI_System_Time_MS);
L_CO_Timer_400ppm(IN := L_CO_Level_400, PT := T#15m, VI_System_Time_MS := VI_System_Time_MS);

IF L_CO_Timer_30ppm.Q THEN
    VO_CO_Warning_Level := TRUE;
END_IF;

IF L_CO_Timer_70ppm.Q OR L_CO_Timer_400ppm.Q THEN
    VO_CO_Alarm_Level := TRUE;
END_IF;

// --- Smoke ---
L_Smoke_Count := 0;
L_Smoke_Active := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SMOKE_SENSORS DO
    L_Smoke_Timer[L_i](IN := VI_Smoke_Sensors[L_i], PT := T#30s, VI_System_Time_MS := VI_System_Time_MS);

    IF VI_Smoke_Sensors[L_i] THEN
        L_Smoke_Count := L_Smoke_Count + 1;
    END_IF;

    IF L_Smoke_Timer[L_i].Q OR (L_Smoke_Count >= 2) THEN
        L_Smoke_Active := TRUE;
    END_IF;
END_FOR;

IF L_Smoke_Active THEN
    VO_Smoke_Detected := TRUE;
END_IF;

// Status
IF VO_Smoke_Detected THEN
    VO_Status_Msg := 'ПОЖАР';
ELSIF VO_Gas_Detected THEN
    VO_Status_Msg := 'УТЕЧКА ГАЗА';
ELSIF VO_CO_Alarm_Level THEN
    VO_Status_Msg := 'КРИТИЧЕСКИЙ CO';
ELSIF VO_CO_Warning_Level THEN
    VO_Status_Msg := 'ПОВЫШЕННЫЙ CO';
ELSE
    VO_Status_Msg := 'ОК';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Gas_Smoke_Manager <<<

// 1. Error checking and scaling based on sensor type
VO_Error := FALSE;
VO_Diag_Code := 0;

CASE VI_Sensor_Type OF
    0: // 4-20mA (NAMUR NE43: < 3.6mA or > 21mA)
        IF VI_Raw_Value < GVL_CONSTANTS.C_ANALOG_3_6MA_RAW THEN // < 3.6mA (Open circuit)
            VO_Error := TRUE;
            VO_Diag_Code := 1;
        ELSIF VI_Raw_Value > GVL_CONSTANTS.C_ANALOG_21MA_RAW THEN // > 21mA (Short circuit)
            VO_Error := TRUE;
            VO_Diag_Code := 2;
        ELSE
            // 4mA = 5529, 20mA = 27648
            L_Scaled := VI_Min_Scale + (TO_REAL(VI_Raw_Value - GVL_CONSTANTS.C_ANALOG_4MA_RAW) / TO_REAL(GVL_CONSTANTS.C_ANALOG_RAW_MAX - GVL_CONSTANTS.C_ANALOG_4MA_RAW)) * (VI_Max_Scale - VI_Min_Scale);
        END_IF;

    1: // 0-10V (0-27648)
        IF VI_Raw_Value > GVL_CONSTANTS.C_ANALOG_10V_MAX_RAW THEN // Out of range
            VO_Error := TRUE;
            VO_Diag_Code := 3;
        ELSE
            L_Scaled := VI_Min_Scale + (TO_REAL(VI_Raw_Value) / TO_REAL(GVL_CONSTANTS.C_ANALOG_RAW_MAX)) * (VI_Max_Scale - VI_Min_Scale);
        END_IF;

    2: // PT100/1000 (Direct temperature * 10, e.g., 255 = 25.5C)
        // Typically, 16-bit signed integer for temperature
        IF VI_Raw_Value = 16#7FFF OR VI_Raw_Value = 16#8000 THEN // Sensor error codes
            VO_Error := TRUE;
            VO_Diag_Code := 1;
        ELSE
            L_Scaled := TO_REAL(TO_INT(VI_Raw_Value)) / 10.0;
            IF L_Scaled < VI_Min_Scale OR L_Scaled > VI_Max_Scale THEN
                VO_Error := TRUE;
                VO_Diag_Code := 3;
            END_IF;
        END_IF;

    ELSE
        VO_Error := TRUE;
        VO_Diag_Code := 16#FFFF; // Unknown sensor type
END_CASE;

// 2. Fallback handling
IF VO_Error THEN
    IF VI_Fallback_Mode = 1 THEN
        VO_Value := VI_Default_Value;
    END_IF;
    // If VI_Fallback_Mode = 0, VO_Value retains its last good value (L_Filtered)
    RETURN;
END_IF;

// 3. Calibration
L_Scaled := (L_Scaled * VI_Multiplier) + VI_Offset;

// 4. Moving Average Filter (ТЗ 1.2)
IF L_First_Scan THEN
    L_Filtered := L_Scaled;
    L_First_Scan := FALSE;
    L_Last_Time := VI_System_Time_MS;

    // Инициализация массива истории
    FOR L_i := 0 TO 9 DO
        L_History[L_i] := L_Scaled;
    END_FOR;
    L_History_Sum := L_Scaled * 10.0;
    L_History_Count := 10;
    L_History_Idx := 0;
END_IF;

L_DT := (SEL(VI_System_Time_MS >= L_Last_Time, VI_System_Time_MS - L_Last_Time, (4294967295 - L_Last_Time) + VI_System_Time_MS + 1));
IF VI_Filter_Time_MS = 0 THEN
    L_Filtered := L_Scaled;
    L_Last_Time := VI_System_Time_MS;
ELSIF L_DT >= (VI_Filter_Time_MS / 10) THEN // Обновляем 10 раз за время фильтрации
    // Вычитаем старое значение
    L_History_Sum := L_History_Sum - L_History[L_History_Idx];

    // Добавляем новое значение
    L_History[L_History_Idx] := L_Scaled;
    L_History_Sum := L_History_Sum + L_Scaled;

    // Сдвигаем индекс
    L_History_Idx := (L_History_Idx + 1) MOD 10;

    // Вычисляем среднее
    L_Filtered := L_History_Sum / 10.0;

    L_Last_Time := VI_System_Time_MS;
END_IF;

VO_Value := L_Filtered;

// Вспомогательная функция для безопасного вычисления разницы времени
L_Elapsed_Time := (VI_System_Time - L_Last_Pulse_Time);

// 1. Мониторинг "сердцебиения" и расчет сетевых задержек (ТЗ 8.4)
IF VI_Remote_Pulse <> L_Last_Pulse THEN
    // Вычисляем время между изменениями сигнала
    VO_RTT_MS := L_Elapsed_Time;
    // Фиксируем пиковые задержки для диагностики сети
    IF VO_RTT_MS > VO_Max_RTT THEN VO_Max_RTT := VO_RTT_MS; END_IF;
    L_Last_Pulse := VI_Remote_Pulse;
    L_Last_Pulse_Time := VI_System_Time;
    L_Elapsed_Time := 0; // Сбрасываем после обновления
END_IF;

// Подсчет статистики потерь связи (ТЗ 8.4)
IF L_Elapsed_Time > L_Timeout THEN
    IF (VI_System_Time - L_Last_Loss_Time) >= 1000 THEN
        VO_Loss_Count := VO_Loss_Count + 1;
        L_Last_Loss_Time := VI_System_Time;
    END_IF;
ELSE
    L_Last_Loss_Time := VI_System_Time;
END_IF;

// 2. Логика определения роли (Active/Standby) и предотвращение Split-Brain (ТЗ 8.3)
// Уровень 1: Проверка наличия связи с партнером
IF L_Elapsed_Time < L_Timeout THEN
    // Связь есть: Договариваемся о ролях на основе приоритета ID
    IF VI_Local_ID = 1 THEN
        VO_Is_Active := TRUE; // ПЛК А всегда активен при наличии связи
    ELSE
        VO_Is_Active := NOT VI_Remote_Is_Active; // ПЛК B активен только если А не активен
    END_IF;
ELSE
    // Связи нет: Пытаемся определить, кто из нас "живее"
    // Уровень 3: Если связи с партнером нет, проверяем доступность внешнего шлюза
    IF VI_Local_ID = 1 THEN
        // ПЛК А становится активным всегда при потере связи с партнером (fallback)
        VO_Is_Active := TRUE;
    ELSE
        // ПЛК B ждет таймаут удержания роли (2 секунды), прежде чем стать активным
        IF L_Elapsed_Time >= 2000 THEN
            // ПЛК B берет управление если он видит шлюз, а связи с А нет.
            // Если шлюз недоступен, B ждет дольше (fallback).
            IF VI_Gateway_Ping_OK THEN
                VO_Is_Active := TRUE;
            ELSIF L_Elapsed_Time >= 5000 THEN
                VO_Is_Active := TRUE; // Fallback: ПЛК А мертв и шлюз мертв
            ELSE
                VO_Is_Active := FALSE;
            END_IF;
        ELSE
            VO_Is_Active := FALSE;
        END_IF;
    END_IF;
END_IF;

IF VI_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY AND VI_Config.Presence_Simulation_Enabled THEN
    VO_Sim_Active := TRUE;

    // Переключаем свет каждые 30 минут
    IF (VI_System_Time_MS - L_Last_Toggle) >= (GVL_CONSTANTS.C_MS_IN_MINUTE * 30) THEN
        L_Last_Toggle := VI_System_Time_MS;

        FOR L_i := 1 TO 32 DO
            L_Rand_Val := 1;
            VO_Sim_Lights[L_i] := (L_Rand_Val > 80); // 20% шанс включения
        END_FOR;
    END_IF;
ELSE
    VO_Sim_Active := FALSE;
    FOR L_i := 1 TO 32 DO VO_Sim_Lights[L_i] := FALSE; END_FOR;
END_IF;

// Симуляция аварий в тестовом режиме
IF L_Test_Mode THEN
    // Генерация случайных протечек (очень редко)
    L_Rand_Val := 1;
    IF L_Rand_Val = 42 THEN
        VO_Sim_Water_Leak[1] := TRUE;
    END_IF;

    // Симуляция утечки газа
    L_Rand_Val := 1;
    IF L_Rand_Val = 77 THEN
        VO_Sim_Gas_Leak[1] := 15.0; // 15% LEL
    END_IF;
ELSE
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO VO_Sim_Water_Leak[L_i] := FALSE; END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_METHANE_SENSORS DO VO_Sim_Gas_Leak[L_i] := 0.0; END_FOR;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Simulation_Manager <<<

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_OT_Enable[L_i] := FALSE;
    VO_OT_Setpoint[L_i] := 0.0;
    VO_OT_Command_Valid[L_i] := FALSE;

    IF VI_Enable[L_i] AND VI_OT_Online[L_i] AND NOT VI_OT_Error[L_i] THEN
        VO_OT_Enable[L_i] := TRUE;
        VO_OT_Setpoint[L_i] := LIMIT(20.0, VI_Setpoint[L_i], 80.0);
        VO_OT_Command_Valid[L_i] := TRUE;
    END_IF;
END_FOR;

// Расчет ошибки
VO_Error := VI_SetPoint - VI_ProcessValue;

// Проверка мертвой зоны
IF ABS(VO_Error) < VI_Deadband THEN
    VO_Error := 0.0;
END_IF;

IF VI_Reset THEN
    L_Integral_Sum := 0.0;
    L_Prev_Error := 0.0;
    VO_Output := 0.0;
    RETURN;
END_IF;

IF VI_Manual_Mode THEN
    VO_Output := VI_Manual_Value;
    // Безударный переход: при выходе из ручного режима выход должен остаться прежним.
    // Так как Выход = P + I + D, то I = Выход - P - D.
    // Для простоты D при переходе обнуляем (или игнорируем), тогда I = Выход - P.
    L_Integral_Sum := VO_Output - (VI_Kp * VO_Error);
    L_Prev_Error := VO_Error;
    RETURN;
END_IF;

// Пропорциональная составляющая
L_Output_Raw := VI_Kp * VO_Error;

// Интегральная составляющая (Метод трапеций)
IF VI_Tn > 0.0 THEN
    // Anti-windup: не накапливаем интеграл, если выход уже на пределе и ошибка того же знака
    IF NOT VO_Limiting OR (VO_Error > 0.0 AND L_Output_Raw < VI_Y_Max) OR (VO_Error < 0.0 AND L_Output_Raw > VI_Y_Min) THEN
        L_Integral_Sum := L_Integral_Sum + (VI_Kp / VI_Tn) * VO_Error * VI_Cycle_Time_S;
    END_IF;
    L_Output_Raw := L_Output_Raw + L_Integral_Sum;
END_IF;

// Дифференциальная составляющая
IF VI_Tv > 0.0 THEN
    L_Derivative := (VO_Error - L_Prev_Error) / VI_Cycle_Time_S;
    L_Output_Raw := L_Output_Raw + VI_Kp * VI_Tv * L_Derivative;
END_IF;

L_Prev_Error := VO_Error;

// Ограничение выхода
IF L_Output_Raw > VI_Y_Max THEN
    VO_Output := VI_Y_Max;
    VO_Limiting := TRUE;
ELSIF L_Output_Raw < VI_Y_Min THEN
    VO_Output := VI_Y_Min;
    VO_Limiting := TRUE;
ELSE
    VO_Output := L_Output_Raw;
    VO_Limiting := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_PID_Controller <<<

// Сброс выходов по умолчанию
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_Enable[L_i] := FALSE;
    VO_Boiler_Setpoint[L_i] := 0.0;
END_FOR;

// Инициализация ротации
IF NOT L_Rotation_Initialized THEN
    L_Last_Rotation_MS := VI_System_Time_MS;
    L_Rotation_Initialized := TRUE;
END_IF;

// Принудительная остановка
IF VI_Boiler_Stop THEN
    VO_Lead_Boiler := L_Lead_Boiler;
    RETURN;
END_IF;

// Ротация строго каждые 168 часов
IF (VI_System_Time_MS - L_Last_Rotation_MS) >= L_Rotation_Period_MS THEN
    IF GVL_CONSTANTS.C_MAX_BOILERS > 1 THEN
        L_Lead_Boiler := 3 - L_Lead_Boiler;
    END_IF;
    L_Last_Rotation_MS := VI_System_Time_MS;
END_IF;

L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);

L_Lead_Available :=
    VI_Boiler_OT_Online[L_Lead_Boiler] AND
    NOT VI_Boiler_Error_Status[L_Lead_Boiler];

L_Reserve_Available :=
    (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
    VI_Boiler_OT_Online[L_Reserve_Boiler] AND
    NOT VI_Boiler_Error_Status[L_Reserve_Boiler];

// Контроль "команда есть, пламени нет" для ведущего котла
L_Flame_Miss_Timer[L_Lead_Boiler](
    IN := VI_Enable AND L_Lead_Available AND NOT VI_DHW_Heating_Demand AND NOT VI_Boiler_Flame_Status[L_Lead_Boiler],
    PT := T#120s
);

IF L_Flame_Miss_Timer[L_Lead_Boiler].Q AND L_Reserve_Available THEN
    L_Lead_Boiler := L_Reserve_Boiler;
    L_Last_Rotation_MS := VI_System_Time_MS;
    L_Lead_Available :=
        VI_Boiler_OT_Online[L_Lead_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Lead_Boiler];
    L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);
    L_Reserve_Available :=
        (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
        VI_Boiler_OT_Online[L_Reserve_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Reserve_Boiler];
END_IF;

// Нет запроса тепла
IF NOT VI_Enable THEN
    VO_Lead_Boiler := L_Lead_Boiler;
    RETURN;
END_IF;

// Целевая уставка
IF VI_DHW_Heating_Demand THEN
    L_Target_Setpoint := LIMIT(20.0, VI_DHW_Target_Temp + 15.0, 85.0);
ELSE
    L_Target_Setpoint := LIMIT(20.0, VI_Target_Supply_Temp + 5.0, 80.0);
END_IF;

// Выбор ведущего по доступности
IF NOT L_Lead_Available AND L_Reserve_Available THEN
    L_Lead_Boiler := L_Reserve_Boiler;
    L_Lead_Available := TRUE;
    L_Reserve_Boiler := SEL(L_Lead_Boiler = 1, 1, 2);
    L_Reserve_Available :=
        (GVL_CONSTANTS.C_MAX_BOILERS > 1) AND
        VI_Boiler_OT_Online[L_Reserve_Boiler] AND
        NOT VI_Boiler_Error_Status[L_Reserve_Boiler];
END_IF;

// Основной котёл
IF L_Lead_Available THEN
    VO_Boiler_Enable[L_Lead_Boiler] := TRUE;
    VO_Boiler_Setpoint[L_Lead_Boiler] := L_Target_Setpoint;
END_IF;

// Резервный котёл: >80% или отказ основного
L_Start_Reserve :=
    L_Reserve_Available AND
    (
        (VI_Demand_Power > 80.0) OR
        (NOT L_Lead_Available)
    );

IF L_Start_Reserve THEN
    VO_Boiler_Enable[L_Reserve_Boiler] := TRUE;
    VO_Boiler_Setpoint[L_Reserve_Boiler] := L_Target_Setpoint;
END_IF;

VO_Lead_Boiler := L_Lead_Boiler;

// 1. Генерация собственного пульса (меандр 100 мс)
L_Pulse_Timer(IN := NOT L_Pulse_Timer.Q, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
IF L_Pulse_Timer.Q THEN
    L_Pulse_State := NOT L_Pulse_State;
END_IF;
VO_Local_Pulse := L_Pulse_State;

// 2. Определение роли через Heartbeat
L_Heartbeat(
    VI_Local_ID := VI_Local_PLC_ID,
    VI_System_Time := VI_System_Time_MS,
    VI_Remote_Pulse := VI_Remote_Pulse,
    VI_Remote_Is_Active := VI_Remote_Is_Active,
    VI_Gateway_Ping_OK := VI_Gateway_Ping_OK
);

IF L_Heartbeat.VO_Is_Active THEN
    VO_Local_Role := E_PLC_ROLE.ROLE_ACTIVE;
    VO_Status_Msg := 'ПЛК АКТИВЕН (ВЕДУЩИЙ)';
ELSE
    VO_Local_Role := E_PLC_ROLE.ROLE_STANDBY;
    VO_Status_Msg := 'ПЛК В РЕЗЕРВЕ (ВЕДОМЫЙ)';
END_IF;

// 3. Запрос на синхронизацию при переходе в ACTIVE
IF VO_Local_Role = E_PLC_ROLE.ROLE_ACTIVE AND L_Prev_Role = E_PLC_ROLE.ROLE_STANDBY THEN
    VO_Sync_Data_Req := TRUE;
ELSE
    VO_Sync_Data_Req := FALSE;
END_IF;

L_State_Replicator(
    VI_Local_Role := VO_Local_Role,
    VI_Sync_Req := VO_Sync_Data_Req,
    VI_Local_State := VI_Local_State,
    VI_Remote_State := VI_Remote_State,
    VI_System_Time_MS := VI_System_Time_MS
);
VO_Synced_State := L_State_Replicator.VO_Synced_State;
VO_State_Updated := L_State_Replicator.VO_State_Updated;

L_Prev_Role := VO_Local_Role;
// >>> BULK_SYNC_ANCHOR: FB_Redundancy_Manager <<<

// Отслеживание изменения сигнала
IF VI_Heartbeat_Signal <> L_Last_Heartbeat_State THEN
    L_Last_Heartbeat_Time := VI_System_Time_MS;
    L_Last_Heartbeat_State := VI_Heartbeat_Signal;
END_IF;

// Проверка таймаута
L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Last_Heartbeat_Time, VI_System_Time_MS - L_Last_Heartbeat_Time, (4294967295 - L_Last_Heartbeat_Time) + VI_System_Time_MS + 1));

IF L_Elapsed_Time > VI_Timeout_MS THEN
    VO_Module_Online := FALSE;
    VO_Error_Active := TRUE;
ELSE
    VO_Module_Online := TRUE;
    VO_Error_Active := FALSE;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_IO_Module_Watchdog <<<

R_Trig_Start(CLK := VI_Start_Auth);

IF VI_Reset_Success THEN
    VO_State.Is_Success := FALSE;
END_IF;

IF R_Trig_Start.Q AND NOT VO_State.is_pending AND NOT VO_State.Is_Locked THEN
    VO_State.is_pending := TRUE;
    VO_State.Auth_Method := VI_Method;
    L_Start_Time := VI_System_Time_MS;
    VO_State.Attempts_Left := 3;
    VO_State.Is_Success := FALSE;
    VO_State.Is_Locked := FALSE;
    L_Prev_User_Code := '';

    IF VI_Method <> E_TwoFactor_Method.TF_METHOD_TOTP THEN
        // Генерируем одноразовый код через HMAC (без упрощенного алгоритма "по времени")
        L_Time_Step := VI_System_Time_MS / 30000;
        L_Key[0] := 16#31; L_Key[1] := 16#32; L_Key[2] := 16#33; L_Key[3] := 16#34; // Секрет-шаблон, заменяется из конфигурации
        FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step + L_Start_Time, L_i * 8) AND 16#FF); END_FOR;
        fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
        L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
        L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
        L_Generated_Code := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
        WHILE LEN(L_Generated_Code) < 6 DO
            L_Generated_Code := CONCAT('0', L_Generated_Code);
        END_WHILE;

        VO_Code_To_Send := L_Generated_Code;
        VO_Send_Code_Req := TRUE;
    ELSE
        // Для TOTP код не отправляем
        VO_Code_To_Send := '';
        VO_Send_Code_Req := FALSE;
    END_IF;
ELSE
    VO_Send_Code_Req := FALSE;
END_IF;

IF VO_State.is_pending THEN
    L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1));

    IF L_Elapsed_Time < (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.Time_Left_S := TO_UINT(((GVL_CONSTANTS.C_MS_IN_MINUTE * 5) - L_Elapsed_Time) / 1000);
    ELSE
        VO_State.Time_Left_S := 0;
    END_IF;

    IF VI_User_Code <> '' AND VI_User_Code <> L_Prev_User_Code THEN
        L_Code_Valid := FALSE;

        IF VI_Method = E_TwoFactor_Method.TF_METHOD_TOTP THEN
            // Вычисляем TOTP для текущего шага времени (30 секунд)
            L_Time_Step := VI_System_Time_MS / 30000; 

            // Подготовка ключа (в реальном проекте берется из GVL_CONFIG)
            L_Key[0] := 16#31; L_Key[1] := 16#32; L_Key[2] := 16#33; L_Key[3] := 16#34; // '1234'

            // Проверка текущего шага
            FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step, L_i * 8) AND 16#FF); END_FOR;
            fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
            L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
            L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
            L_Current_TOTP := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
            WHILE LEN(L_Current_TOTP) < 6 DO L_Current_TOTP := CONCAT('0', L_Current_TOTP); END_WHILE;

            // Проверка предыдущего шага (для компенсации рассинхронизации)
            FOR L_i := 0 TO 7 DO L_Message[7 - L_i] := TO_BYTE(SHR(L_Time_Step - 1, L_i * 8) AND 16#FF); END_FOR;
            fbHMAC(Key := L_Key, KeyLength := 4, Message := L_Message, MessageLength := 8);
            L_Offset := TO_INT(fbHMAC.Hash[19] AND 16#0F);
            L_Truncated_Hash := (SHL(TO_UDINT(fbHMAC.Hash[L_Offset] AND 16#7F), 24) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+1] AND 16#FF), 16) OR SHL(TO_UDINT(fbHMAC.Hash[L_Offset+2] AND 16#FF), 8) OR TO_UDINT(fbHMAC.Hash[L_Offset+3] AND 16#FF));
            L_Prev_TOTP := UDINT_TO_STRING(L_Truncated_Hash MOD 1000000);
            WHILE LEN(L_Prev_TOTP) < 6 DO L_Prev_TOTP := CONCAT('0', L_Prev_TOTP); END_WHILE;

            IF VI_User_Code = L_Current_TOTP OR VI_User_Code = L_Prev_TOTP THEN
                L_Code_Valid := TRUE;
            END_IF;
        ELSE
            IF VI_User_Code = L_Generated_Code THEN
                L_Code_Valid := TRUE;
            END_IF;
        END_IF;

        IF L_Code_Valid THEN
            VO_State.Is_Success := TRUE;
            VO_State.is_pending := FALSE;
        ELSE
            IF VO_State.Attempts_Left > 0 THEN
                VO_State.Attempts_Left := VO_State.Attempts_Left - 1;
            END_IF;

            IF VO_State.Attempts_Left = 0 THEN
                VO_State.Is_Locked := TRUE;
                VO_State.is_pending := FALSE;
                L_Lockout_Start_Time := VI_System_Time_MS; // Блокировка на 5 минут
            END_IF;
        END_IF;
    END_IF;
    L_Prev_User_Code := VI_User_Code;

    IF L_Elapsed_Time > (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.is_pending := FALSE; // Таймаут
    END_IF;
END_IF;

IF VO_State.Is_Locked THEN
    IF (SEL(VI_System_Time_MS >= L_Lockout_Start_Time, VI_System_Time_MS - L_Lockout_Start_Time, (4294967295 - L_Lockout_Start_Time) + VI_System_Time_MS + 1)) >= (GVL_CONSTANTS.C_MS_IN_MINUTE * 5) THEN
        VO_State.Is_Locked := FALSE;
    END_IF;
END_IF;

// 1. Расчет калиброванного значения
CASE VI_Type OF
    1: VO_Calibrated_Value := VI_Raw_Value + VI_Calib_Record.offset;
    2, 3: VO_Calibrated_Value := (VI_Raw_Value * VI_Calib_Record.multiplier) + VI_Calib_Record.offset;
END_CASE;

// 2. Верификация через 1 час (ТЗ 9.5)
IF VI_Start_Verification AND NOT VO_Verification_Active THEN
    VO_Verification_Active := TRUE;
    L_Initial_Value := VO_Calibrated_Value;
END_IF;

L_Verification_Timer(IN := VO_Verification_Active, PT := T#1h, VI_System_Time_MS := VI_System_Time_MS);

IF L_Verification_Timer.Q THEN
    VO_Verification_Active := FALSE;

    // ТЗ 9.5: Отклонение ≤2.0% (норма) / >5.0% (ошибка)
    IF L_Initial_Value <> 0 THEN
        VO_Deviation_Percent := ABS(VO_Calibrated_Value - L_Initial_Value) / L_Initial_Value * 100.0;
    ELSE
        VO_Deviation_Percent := 0.0;
    END_IF;

    VO_Verification_Failed := (VO_Deviation_Percent > 5.0);
END_IF;

IF NOT VI_IsActivePLC THEN
    RETURN;
END_IF;

CASE VI_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP,
    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        IF VO_Current_Scenario <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
            VO_Current_Scenario := E_SCENARIO_TYPE.SCENARIO_NONE;
            VO_Status_Msg := 'Сценарии принудительно отключены режимом безопасности';
        END_IF;
        RETURN;

    E_System_Operating_Mode.MODE_DEGRADED:
        VO_Status_Msg := 'Смена сценариев заблокирована: деградированный режим';
        RETURN;
END_CASE;

IF VI_Activate_Request <> VO_Current_Scenario THEN
    // Проверка минимального времени работы сценария
    IF (VI_System_Time_MS - L_Last_Scenario_Time) >= 60000 OR VO_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_NONE THEN
        // Логика переключения сценариев
        VO_Current_Scenario := VI_Activate_Request;
        L_Last_Scenario_Time := VI_System_Time_MS;

        CASE VO_Current_Scenario OF
        E_SCENARIO_TYPE.SCENARIO_NONE:
            VO_Status_Msg := 'Сценарии отключены';
        E_SCENARIO_TYPE.SCENARIO_AWAY:
            VO_Status_Msg := 'Активирован сценарий: Вне дома (Охрана + Энергосбережение)';
        E_SCENARIO_TYPE.SCENARIO_SLEEP:
            VO_Status_Msg := 'Активирован сценарий: Сон (Ночное освещение + Климат)';
        E_SCENARIO_TYPE.SCENARIO_PRESENCE:
            VO_Status_Msg := 'Активирован сценарий: Имитация присутствия';
        END_CASE;
    END_IF;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Scenario_Manager <<<


// --- PREHEAT SCENARIO INSERT ---
IF VI_Preheat_Request THEN
    // removed: direct heating write (moved to Heating Manager)
END_IF;

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

VO_Preheat_Request := FALSE;


// Сброс счетчиков срабатываний каждую минуту (защита от циклических зависимостей/дребезга)
L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Last_Reset_Time, VI_System_Time_MS - L_Last_Reset_Time, (4294967295 - L_Last_Reset_Time) + VI_System_Time_MS + 1));

IF L_Elapsed_Time >= GVL_CONSTANTS.C_MS_IN_MINUTE THEN
    L_Last_Reset_Time := VI_System_Time_MS;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        L_Trigger_Count[L_i] := 0;
    END_FOR;
END_IF;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_RULES DO

    VO_Actions[L_i].Active := FALSE;
    IF VI_Rules[L_i].Enabled THEN
        L_Condition_Met := FALSE;
        L_Current_Value := 0.0;

        // Определение значения для проверки
        IF VI_Rules[L_i].Condition_Target_ID > 0 THEN
            CASE VI_Rules[L_i].Condition_Type OF
                E_Rule_Condition_Type.COND_AIR_TEMP: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := VI_Indoor_Temps[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_FLOOR_TEMP: IF VI_Rules[L_i].Condition_Target_ID <= 8 THEN L_Current_Value := VI_Floor_Temps[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_HUMIDITY: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := VI_Humidities[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_CO2: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := VI_CO2_Levels[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_MOTION: IF VI_Rules[L_i].Condition_Target_ID <= 16 THEN L_Current_Value := SEL(VI_Motion_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_DOOR_WINDOW: 
                    IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_DOOR_SENSORS THEN
                        L_Current_Value := SEL(VI_Door_Sensors[VI_Rules[L_i].Condition_Target_ID] OR VI_Window_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    ELSIF VI_Rules[L_i].Condition_Target_ID <= 16 THEN
                        L_Current_Value := SEL(VI_Window_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0);
                    END_IF;
                E_Rule_Condition_Type.COND_FLOOD: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_FLOOD_SENSORS THEN L_Current_Value := SEL(VI_Water_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_SMOKE: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_SMOKE_SENSORS THEN L_Current_Value := SEL(VI_Smoke_Sensors[VI_Rules[L_i].Condition_Target_ID], 0.0, 1.0); END_IF;
                E_Rule_Condition_Type.COND_METHANE: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_METHANE_SENSORS THEN L_Current_Value := VI_Methane_Sensors[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_CO: IF VI_Rules[L_i].Condition_Target_ID <= GVL_CONSTANTS.C_MAX_CO_SENSORS THEN L_Current_Value := VI_CO_Sensors[VI_Rules[L_i].Condition_Target_ID]; END_IF;
                E_Rule_Condition_Type.COND_TIME_OF_DAY: L_Current_Value := TO_REAL(TOD_TO_UDINT(VI_Current_Time) / GVL_CONSTANTS.C_MS_IN_MINUTE); // Время в минутах
                E_Rule_Condition_Type.COND_DAY_OF_WEEK: L_Current_Value := TO_REAL(VI_Day_Of_Week);
            END_CASE;
        ELSE
            IF VI_Rules[L_i].Condition_Type = E_Rule_Condition_Type.COND_TIME_OF_DAY THEN
                L_Current_Value := TO_REAL(TOD_TO_UDINT(VI_Current_Time) / GVL_CONSTANTS.C_MS_IN_MINUTE); // Время в минутах
            ELSIF VI_Rules[L_i].Condition_Type = E_Rule_Condition_Type.COND_DAY_OF_WEEK THEN
                L_Current_Value := TO_REAL(VI_Day_Of_Week);
            END_IF;
        END_IF;

        // Проверка условия
        CASE VI_Rules[L_i].Condition_Op OF
            E_Rule_Comparison.COMP_GT: L_Condition_Met := (L_Current_Value > VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_LT: L_Condition_Met := (L_Current_Value < VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_EQ: L_Condition_Met := (ABS(L_Current_Value - VI_Rules[L_i].Condition_Value) < 0.1);
            E_Rule_Comparison.COMP_GE: L_Condition_Met := (L_Current_Value >= VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_LE: L_Condition_Met := (L_Current_Value <= VI_Rules[L_i].Condition_Value);
            E_Rule_Comparison.COMP_IN_RANGE: L_Condition_Met := (L_Current_Value >= VI_Rules[L_i].Condition_Value) AND (L_Current_Value <= VI_Rules[L_i].Condition_Value_Max);
            E_Rule_Comparison.COMP_TRUE: L_Condition_Met := (L_Current_Value > 0.5);
            E_Rule_Comparison.COMP_FALSE: L_Condition_Met := (L_Current_Value < 0.5);
        END_CASE;

        // Формирование действия
        L_Triggers[L_i](CLK := L_Condition_Met);

        IF L_Triggers[L_i].Q THEN
            L_Trigger_Count[L_i] := L_Trigger_Count[L_i] + 1;
            IF L_Trigger_Count[L_i] > 10 THEN
                // ТЗ 13.5: Блокировка правила при слишком частом срабатывании (циклическая зависимость)
                VO_Actions[L_i].Active := FALSE;
                VO_Actions[L_i].Triggered := FALSE;
                CONTINUE; // Пропускаем выполнение
            END_IF;
        END_IF;

        IF L_Condition_Met AND (L_Trigger_Count[L_i] <= 10) THEN
            VO_Actions[L_i].Active := TRUE;
            VO_Actions[L_i].Triggered := L_Triggers[L_i].Q;
            VO_Actions[L_i].Action_Type := VI_Rules[L_i].Action_Type;
            VO_Actions[L_i].Target_ID := VI_Rules[L_i].Action_Target_ID;
            VO_Actions[L_i].Value := VI_Rules[L_i].Action_Value;
        END_IF;
    END_IF;
END_FOR;
// >>> BULK_SYNC_ANCHOR: FB_Rule_Engine <<<

IF VI_Count > 0 AND VI_Count <= GVL_CONSTANTS.C_MAX_TREND_DATA_POINTS THEN
    VO_Max := VI_Data[1];
    VO_Min := VI_Data[1];
    L_Sum := 0.0;

    FOR L_i := 1 TO VI_Count DO
        IF VI_Data[L_i] > VO_Max THEN VO_Max := VI_Data[L_i]; END_IF;
        IF VI_Data[L_i] < VO_Min THEN VO_Min := VI_Data[L_i]; END_IF;
        L_Sum := L_Sum + VI_Data[L_i];
    END_FOR;

    VO_Average := L_Sum / INT_TO_REAL(VI_Count);

    IF VI_Count >= 2 THEN
        VO_Trend_Up := (VI_Data[VI_Count] > VI_Data[1]);
        VO_Trend_Down := (VI_Data[VI_Count] < VI_Data[1]);
    END_IF;
END_IF;

IF NOT L_Initialized THEN
    L_Write_Index := GVL_Retain.G_BlackBox_LastIndex;
    IF L_Write_Index < 0 OR L_Write_Index >= GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS THEN
        L_Write_Index := 0;
        GVL_Retain.G_BlackBox_LastIndex := 0;
    END_IF;
    L_Initialized := TRUE;
END_IF;

IF VI_Freeze THEN
    GVL_Retain.G_BlackBox_Frozen := TRUE;
END_IF;

VO_Frozen := GVL_Retain.G_BlackBox_Frozen;

IF NOT GVL_Retain.G_BlackBox_Frozen THEN
    GVL_Retain.G_BlackBox_Buffer[L_Write_Index] := VI_Current_Data;
    GVL_Retain.G_BlackBox_LastIndex := L_Write_Index;

    L_Write_Index := L_Write_Index + 1;
    IF L_Write_Index >= GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS THEN
        L_Write_Index := 0;
    END_IF;
END_IF;

VO_Records_Count := GVL_CONSTANTS.C_MAX_BLACKBOX_RECORDS; // Размер кольцевого буфера
// >>> BULK_SYNC_ANCHOR: FB_BlackBox_Recorder <<<

// Защёлкиваем аварии независимо друг от друга
IF VI_Gas_Alarm THEN
    VO_Gas_Latched := TRUE;
END_IF;

IF VI_Leak_Alarm THEN
    VO_Leak_Latched := TRUE;
END_IF;

IF VI_Smoke_Alarm THEN
    VO_Smoke_Latched := TRUE;
END_IF;

L_Any_Active := VI_Gas_Alarm OR VI_Leak_Alarm OR VI_Smoke_Alarm;

// Ручной сброс допустим только когда все входные аварийные сигналы уже исчезли
IF VI_Reset AND NOT L_Any_Active THEN
    VO_Gas_Latched := FALSE;
    VO_Leak_Latched := FALSE;
    VO_Smoke_Latched := FALSE;
END_IF;

// Агрегированный аварийный стоп = любая защёлкнутая safety-авария
VO_Emergency_Stop := VO_Gas_Latched OR VO_Leak_Latched OR VO_Smoke_Latched;

// >>> BULK_SYNC_ANCHOR: FB_Safety_Manager <<<

// ==============================================================================
// Блок управления системой отопления (Heating System Manager)
// Назначение:
// - Управление контурами теплого пола (открытие/закрытие клапанов).
// - Управление насосами коллекторов и смесительными узлами.
// - Управление каскадом котлов (ротация, расчет ресурса).
// - Защита от перегрева и замерзания.
// - Интеграция с Rule Engine.
// ==============================================================================





// ========================================
// Heating policy layer
// ========================================
L_Policy_Normal := (VI_System_Mode = E_System_Operating_Mode.MODE_NORMAL);
L_Policy_Safe_Stop := (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
L_Policy_Freeze_Protection := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);

// ========================================
// Heating freeze policy activation
// ========================================
IF L_Policy_Freeze_Protection THEN
    L_Freeze_Mode_Active := TRUE;
END_IF;

// 0. Агрегация деградации для system mode
GVL_STATE.G_Heating_IO_Fault := FALSE;
GVL_STATE.G_Heating_Sensor_Fault := FALSE;
GVL_STATE.G_Heating_Subsystem_Degraded := FALSE;
L_Any_Sensor_Error := FALSE;
L_Any_Subsystem_Degraded := FALSE;

// 0. Аварийный стоп от подсистемы безопасности
VO_Backup_Circulation_Pump := FALSE;
VO_Electric_Heater_Enable := FALSE;
VO_Freeze_Risk_Status := FALSE;

IF VI_Gas_Safety_Stop THEN
    L_Freeze_Mode_Active := (VI_Outdoor_Temp < -5.0);
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        IF VI_Floor_Temps[L_i] < 7.0 THEN
            L_Freeze_Mode_Active := TRUE;
        END_IF;
        VO_Zone_Valves[L_i] := FALSE;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        VO_Manifold_Pumps[L_i] := FALSE;
        VO_Manifold_Valves[L_i] := 0.0;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Boiler_OT_Enable[L_i] := FALSE;
        VO_Boiler_OT_Setpoint[L_i] := 0.0;
        VO_Boiler_Status[L_i].Warning := FALSE;
        VO_Boiler_Status[L_i].Error := TRUE;
    END_FOR;

    IF L_Freeze_Mode_Active THEN
        VO_Backup_Circulation_Pump := TRUE;
        L_Freeze_Target_Supply := LIMIT(20.0, VI_Config.Freeze_Threshold + 2.0, 35.0);
        L_Min_Supply_Temp := 1000.0;
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            IF VI_Manifold_Temps_Supply[L_i] < L_Min_Supply_Temp THEN
                L_Min_Supply_Temp := VI_Manifold_Temps_Supply[L_i];
            END_IF;
        END_FOR;
        IF L_Min_Supply_Temp > 900.0 THEN
            L_Min_Supply_Temp := 0.0;
        END_IF;

        IF L_Min_Supply_Temp < (L_Freeze_Target_Supply - 1.0) THEN
            VO_Electric_Heater_Enable := TRUE;
        ELSIF L_Min_Supply_Temp > (L_Freeze_Target_Supply + 1.0) THEN
            VO_Electric_Heater_Enable := FALSE;
        END_IF;

        // При защёлкнутой газовой аварии оператор должен видеть, что система живёт в деградированном anti-freeze режиме.
        VO_Freeze_Risk_Status := TRUE;
    END_IF;

    RETURN;
END_IF;

IF VI_Emergency_Stop OR L_Policy_Safe_Stop THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        VO_Zone_Valves[L_i] := FALSE;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        VO_Manifold_Pumps[L_i] := FALSE;
        VO_Manifold_Valves[L_i] := 0.0;
    END_FOR;

    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Boiler_OT_Enable[L_i] := FALSE;
        VO_Boiler_OT_Setpoint[L_i] := 0.0;
        VO_Boiler_Status[L_i].Warning := FALSE;
        VO_Boiler_Status[L_i].Error := TRUE;
    END_FOR;

    RETURN;
END_IF;

// 1. Проверка связи с модулями ввода-вывода (ТЗ 2.0)
L_IO_Failsafe_Active := FALSE;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        L_IO_Failsafe_Active := TRUE;
        GVL_STATE.G_Heating_IO_Fault := TRUE;
GVL_STATE.G_Heating_Subsystem_Degraded := TRUE;
        EXIT;
    END_IF;
END_FOR;

IF L_IO_Failsafe_Active THEN
    // Fail-safe: закрываем зональные клапаны, чтобы не разгонять неконтролируемые контуры,
    // но при риске замерзания сохраняем минимальную циркуляцию и минимальную теплогенерацию.
    L_Freeze_Mode_Active := (VI_Outdoor_Temp < -5.0);

    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
        IF VI_Floor_Temps[L_j] < 7.0 THEN
            L_Freeze_Mode_Active := TRUE;
        END_IF;
        VO_Zone_Valves[L_j] := FALSE;
    END_FOR;

    IF L_Freeze_Mode_Active THEN
        L_Freeze_Target_Supply := LIMIT(20.0, VI_Config.Freeze_Threshold + 2.0, 35.0);
    ELSE
        L_Freeze_Target_Supply := 0.0;
    END_IF;

    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        IF L_Freeze_Mode_Active THEN
            VO_Manifold_Pumps[L_j] := TRUE;
            VO_Manifold_Valves[L_j] := 35.0;
        ELSE
            VO_Manifold_Pumps[L_j] := FALSE;
            VO_Manifold_Valves[L_j] := 0.0;
        END_IF;
    END_FOR;

    // В аварийном I/O режиме напрямую формируем только legacy request-мirror.
    // Реальные физические команды всё равно будут интерпретированы transport-слоем выше по архитектуре.
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Boiler_OT_Enable[L_j] := FALSE;
        VO_Boiler_OT_Setpoint[L_j] := 0.0;
    END_FOR;

    IF L_Freeze_Mode_Active THEN
        // В fail-safe используем только ведущий аварийный вариант: котёл №1 на минимальной уставке.
        IF VI_Boiler_OT_Online[1] AND NOT VI_Boiler_Error_Status[1] THEN
            VO_Boiler_OT_Enable[1] := TRUE;
            VO_Boiler_OT_Setpoint[1] := L_Freeze_Target_Supply;
        END_IF;
    END_IF;

    RETURN;
END_IF;



// --- HEATING TARGET INJECTION ---
// Global arbitration target is applied after base policy calculation.
IF GVL_STATE.G_Target_Temperature > 0.0 THEN
    L_Target_Supply_Temp := GVL_STATE.G_Target_Temperature;
END_IF;

// --- MULTI-ZONE ADAPTIVE CORRECTION ---
// Final adaptive refinement layer.
L_Adaptive_Max_Delta := 0.0;
L_Adaptive_Weighted_Sum := 0.0;
L_Adaptive_Weight_Total := 0.0;
L_Adaptive_Effective_Delta := 0.0;
L_Adaptive_Correction := 0.0;

FOR L_Adaptive_Zone_i := 1 TO 8 DO
    IF VI_Zone_Configs[L_Adaptive_Zone_i].zone >= 1 AND VI_Zone_Configs[L_Adaptive_Zone_i].zone <= 8 THEN
        CASE VI_Zone_Configs[L_Adaptive_Zone_i].control_type OF
            0:
                L_Adaptive_Delta :=
                    VI_Zone_Configs[L_Adaptive_Zone_i].design_temp -
                    VI_Floor_Temps[L_Adaptive_Zone_i];
                L_Adaptive_Weight := 0.6;
            1, 2:
                L_Adaptive_Delta :=
                    VI_Zone_Configs[L_Adaptive_Zone_i].design_temp -
                    VI_Room_Temps[VI_Zone_Configs[L_Adaptive_Zone_i].zone];
                L_Adaptive_Weight := 1.0;
            ELSE
                L_Adaptive_Delta :=
                    VI_Zone_Configs[L_Adaptive_Zone_i].design_temp -
                    VI_Room_Temps[VI_Zone_Configs[L_Adaptive_Zone_i].zone];
                L_Adaptive_Weight := 0.8;
        END_CASE;

        IF VI_Zone_Configs[L_Adaptive_Zone_i].zone >= 1 AND VI_Zone_Configs[L_Adaptive_Zone_i].zone <= 4 THEN
            L_Adaptive_Weight := L_Adaptive_Weight * 1.2;
        ELSIF VI_Zone_Configs[L_Adaptive_Zone_i].zone >= 9 THEN
            L_Adaptive_Weight := L_Adaptive_Weight * 0.7;
        END_IF;

        IF L_Adaptive_Weight > 2.0 THEN
            L_Adaptive_Weight := 2.0;
        ELSIF L_Adaptive_Weight < 0.2 THEN
            L_Adaptive_Weight := 0.2;
        END_IF;

        IF L_Adaptive_Delta > L_Adaptive_Max_Delta THEN
            L_Adaptive_Max_Delta := L_Adaptive_Delta;
        END_IF;

        L_Adaptive_Weighted_Sum := L_Adaptive_Weighted_Sum + (L_Adaptive_Delta * L_Adaptive_Weight);
        L_Adaptive_Weight_Total := L_Adaptive_Weight_Total + L_Adaptive_Weight;
    END_IF;
END_FOR;

IF L_Adaptive_Weight_Total > 0.0 THEN
    L_Adaptive_Effective_Delta := L_Adaptive_Weighted_Sum / L_Adaptive_Weight_Total;
END_IF;

IF L_Adaptive_Effective_Delta > 1.5 THEN
    L_Adaptive_Correction := 2.0;
ELSIF L_Adaptive_Effective_Delta > 0.7 THEN
    L_Adaptive_Correction := 1.0;
ELSIF L_Adaptive_Effective_Delta < -1.5 THEN
    L_Adaptive_Correction := -2.0;
ELSIF L_Adaptive_Effective_Delta < -0.7 THEN
    L_Adaptive_Correction := -1.0;
ELSE
    L_Adaptive_Correction := 0.0;
END_IF;

IF L_Adaptive_Max_Delta > 2.5 AND L_Adaptive_Correction < 2.0 THEN
    L_Adaptive_Correction := 2.0;
END_IF;

L_Target_Supply_Temp := L_Target_Supply_Temp + L_Adaptive_Correction;

IF L_Target_Supply_Temp < 20.0 THEN
    L_Target_Supply_Temp := 20.0;
ELSIF L_Target_Supply_Temp > 45.0 THEN
    L_Target_Supply_Temp := 45.0;
END_IF;

// 2. Индивидуальное управление зонами отопления (ТЗ 1.1, 2.5)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    fbFloorTempValidator[L_i](
        VI_Value := VI_Floor_Temps[L_i],
        VI_Min_Valid := -40.0,
        VI_Max_Valid := 120.0,
        VI_Fallback_Mode := 0
    );

    L_Climate_Zone_ID := VI_Zone_Configs[L_i].zone;
    IF L_Climate_Zone_ID >= 1 AND L_Climate_Zone_ID <= 16 THEN
        fbRoomTempValidator[L_Climate_Zone_ID](
        VI_Value := VI_Room_Temps[L_Climate_Zone_ID],
        VI_Min_Valid := -40.0,
        VI_Max_Valid := 120.0,
        VI_Fallback_Mode := 0
        );
    END_IF;

    // Контроль перегрева стяжки (защита напольного покрытия)
    L_Overheat_Timer[L_i](IN := fbFloorTempValidator[L_i].VO_Value > VI_Config.Overheat_Threshold, PT := T#60s, VI_System_Time_MS := VI_System_Time_MS);

    // Выбор датчика температуры с автоматическим переключением при неисправности
    L_Current_Temp := 0.0;
    L_Sensor_Error := FALSE;

    IF VI_Zone_Configs[L_i].control_type = 1 OR VI_Zone_Configs[L_i].control_type = 2 THEN
        // Основной: по воздуху
        IF NOT fbRoomTempValidator[L_Climate_Zone_ID].VO_Error THEN
            L_Current_Temp := fbRoomTempValidator[L_Climate_Zone_ID].VO_Value;
        ELSIF NOT fbFloorTempValidator[L_i].VO_Error THEN
            L_Current_Temp := fbFloorTempValidator[L_i].VO_Value; // Резервный: по полу
        ELSE
            L_Sensor_Error := TRUE;
        END_IF;
    ELSE
        // Основной: по полу
        IF NOT fbFloorTempValidator[L_i].VO_Error THEN
            L_Current_Temp := fbFloorTempValidator[L_i].VO_Value;
        ELSIF NOT fbRoomTempValidator[L_Climate_Zone_ID].VO_Error THEN
            L_Current_Temp := fbRoomTempValidator[L_Climate_Zone_ID].VO_Value; // Резервный: по воздуху
        ELSE
            L_Sensor_Error := TRUE;
        END_IF;
    END_IF;

    IF L_Sensor_Error THEN
        L_Any_Sensor_Error := TRUE;
        VO_Zone_Valves[L_i] := FALSE; // Безопасное состояние при ошибке обоих датчиков
    ELSE
        // ПИД-регулирование и ШИМ для каждой зоны
        // Применяем плавную корректировку уставки от сценария
        L_Zone_Config := VI_Zone_Configs[L_i];
        L_Zone_Config.design_temp := L_Zone_Config.design_temp + L_Scenario_Adjust;
        L_Floor_Controllers[L_i](
            VI_Current_Temp := L_Current_Temp,
            VI_Config := L_Zone_Config,
            VI_Tariff := VI_Tariff,
            VI_Current_Hour := VI_Current_Hour,
            VI_IsActivePLC := VI_IsActivePLC,
            VI_System_Time_MS := VI_System_Time_MS,
            VO_Valve_Bool => VO_Zone_Valves[L_i]
        );
    END_IF;

    // Принудительное закрытие клапана при перегреве пола (ТЗ 2.5)
    IF L_Overheat_Timer[L_i].Q THEN
        VO_Zone_Valves[L_i] := FALSE;
    END_IF;

    // Обработка действий от Rule Engine (ТЗ 13.0)
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_FLOOR_HEATING THEN
                VO_Zone_Valves[L_i] := (VI_Rule_Actions[L_j].Value > 0.5);
            END_IF;
        END_IF;
    END_FOR;
END_FOR;

GVL_STATE.G_Heating_Sensor_Fault := L_Any_Sensor_Error;

// 3. Определение потребности в работе коллекторных насосов
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    L_Any_Zone_Active[L_i] := FALSE;
END_FOR;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VO_Zone_Valves[L_i] THEN
        L_j := VI_Zone_Configs[L_i].manifold_id;
        IF L_j >= 1 AND L_j <= GVL_CONSTANTS.C_MAX_MANIFOLDS THEN
            L_Any_Zone_Active[L_j] := TRUE;
        END_IF;
    END_IF;
END_FOR;

// 4. Управление смесительными узлами коллекторов (ТЗ 2.6, 12.2)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    // ПИД-регулирование трехходового клапана для поддержания стабильной температуры подачи
    // Вызываем ПИД регулятор каждую секунду
    L_PID_Timer[L_i](IN := TRUE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS);
    IF L_PID_Timer[L_i].Q THEN
        L_PID_Timer[L_i](IN := FALSE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS); // Сброс таймера
        L_PID_Timer[L_i](IN := TRUE, PT := T#1s, VI_System_Time_MS := VI_System_Time_MS); // Перезапуск

        L_PID_Valves[L_i](
            VI_SetPoint := L_Target_Supply_Temp,
            VI_ProcessValue := VI_Manifold_Temps_Supply[L_i],
            VI_Kp := 2.0, VI_Tn := 120.0, VI_Tv := 0.0,
            VI_Y_Min := 0.0, VI_Y_Max := 100.0, VI_Cycle_Time_S := 1.0,
            VO_Output => VO_Manifold_Valves[L_i]
        );
    END_IF;

    // ТЗ 2.6: Реализация обязательной паузы насоса (защита от закисания и перегрева при 72ч работе)
    L_Pump_Run_Timer[L_i](IN := VO_Manifold_Pumps[L_i] AND NOT L_Pump_In_Pause[L_i], PT := T#72h, VI_System_Time_MS := VI_System_Time_MS);
    IF L_Pump_Run_Timer[L_i].Q THEN L_Pump_In_Pause[L_i] := TRUE; END_IF;

    L_Pump_Pause_Timer[L_i](IN := L_Pump_In_Pause[L_i], PT := T#1h, VI_System_Time_MS := VI_System_Time_MS);
    IF L_Pump_Pause_Timer[L_i].Q THEN L_Pump_In_Pause[L_i] := FALSE; END_IF;

    // Включение насоса при наличии запроса от зон и отсутствии сервисной паузы
    // Приоритет ГВС: если есть запрос от ГВС, отключаем насосы отопления и закрываем клапаны
    IF VI_DHW_Heating_Demand THEN
        VO_Manifold_Pumps[L_i] := FALSE;
        VO_Manifold_Valves[L_i] := 0.0; // Принудительно закрываем смесительный клапан
    ELSE
        VO_Manifold_Pumps[L_i] := VI_IsActivePLC AND L_Any_Zone_Active[L_i] AND NOT L_Pump_In_Pause[L_i];
    END_IF;

    // Защита от замерзания системы (ТЗ 2.4)
        IF L_Freeze_Mode_Active THEN
            VO_Manifold_Pumps[L_i] := TRUE;
            IF VO_Manifold_Valves[L_i] < 35.0 THEN
                VO_Manifold_Valves[L_i] := 35.0;
            END_IF;
        END_IF;

        // Сбор диагностических данных для визуализации на HMI
    VO_Status[L_i].Pump_On := VO_Manifold_Pumps[L_i];
    VO_Status[L_i].Pump_Current := VI_Manifold_Currents[L_i];
    VO_Status[L_i].Pressure := VI_Manifold_Pressures[L_i];
    VO_Status[L_i].Temp_Supply := VI_Manifold_Temps_Supply[L_i];
    VO_Status[L_i].Temp_Return := VI_Manifold_Temps_Return[L_i];
    VO_Status[L_i].Valve_Pos := VO_Manifold_Valves[L_i];

    // Предиктивная диагностика насоса
    L_Pump_Diag[L_i](
        VI_Current_Value := VI_Manifold_Currents[L_i],
        VI_Nominal_Value := 0.55, // Номинальный ток насоса по ТЗ: середина диапазона 0.3..0.8 А
        VI_Is_Running := VO_Manifold_Pumps[L_i],
        VI_Reset_Stats := FALSE,
        VI_System_Time_MS := VI_System_Time_MS,
        VIO_Health_Data := VO_Status[L_i].Health
    );

    // Автоматический контроль рабочих параметров (ток / давление / ΔT)
        IF VO_Manifold_Pumps[L_i] THEN
            L_Delta_T := VI_Manifold_Temps_Supply[L_i] - VI_Manifold_Temps_Return[L_i];

            // Контроль тока насоса:
            // Приоритет ошибок:
            // 1. Насос/ток
            // 2. Давление
            // 3. ΔT
            VO_Status[L_i].Error := FALSE;
            VO_Status[L_i].Error_ID := 0;

            IF VI_Manifold_Currents[L_i] <= 0.01 THEN
                VO_Status[L_i].Error := TRUE;
                VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_NO_CURRENT);
            ELSIF VI_Manifold_Currents[L_i] < 0.3 THEN
                VO_Status[L_i].Error := TRUE;
                VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_UNDERCURRENT);
            ELSIF VI_Manifold_Currents[L_i] > 1.5 THEN
                VO_Status[L_i].Error := TRUE;
                VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PUMP_OVERCURRENT);
            END_IF;

            // Проверка давления в системе (норма 1.5 - 2.5 бар)
            IF (NOT VO_Status[L_i].Error) AND (VI_Manifold_Pressures[L_i] < 1.5 OR VI_Manifold_Pressures[L_i] > 2.5) THEN
                VO_Status[L_i].Error := TRUE;
                VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_PRESSURE_OUT_OF_RANGE);
            END_IF;

            // Проверка эффективности теплообмена (ΔT 5..10°C норма)
            IF NOT VO_Status[L_i].Error THEN
                IF L_Delta_T < 5.0 THEN
                    VO_Status[L_i].Error := TRUE;
                    VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_DELTA_T_LOW);
                ELSIF L_Delta_T > 10.0 THEN
                    VO_Status[L_i].Error := TRUE;
                    VO_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_DELTA_T_HIGH);
                END_IF;
            END_IF;
        END_IF;

        // ТЗ 12.2: Еженедельное тестирование запорной арматуры (предотвращение закисания)
    // Выполняется менеджером fbValveTestManager
END_FOR;

fbValveTestManager(
    VI_System_Time_MS := VI_System_Time_MS,
    VI_IsActivePLC := VI_IsActivePLC,
    VI_Valve_Currents := VI_Manifold_Currents,
    VI_Valve_End_Switches := VI_Manifold_End_Switches,
    VI_Config := VI_Valve_Test_Config
);

IF fbValveTestManager.VO_Test_Active THEN
    L_i := fbValveTestManager.VO_Current_Valve;
    IF L_i >= 1 AND L_i <= GVL_CONSTANTS.C_MAX_MANIFOLDS THEN
        IF fbValveTestManager.VO_Valve_Cmd[L_i] THEN
            VO_Manifold_Valves[L_i] := 100.0;
        ELSE
            VO_Manifold_Valves[L_i] := 0.0;
        END_IF;
        VO_Manifold_Pumps[L_i] := FALSE; // Отключаем насос при тестировании клапана
    END_IF;
END_IF;

// 5. Управление каскадом котлов (ТЗ 2.8, OpenTherm-only, без legacy mirror)
L_Demand_Power := 0.0;
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
    IF VO_Manifold_Pumps[L_i] THEN
        L_Demand_Power := L_Demand_Power + VO_Manifold_Valves[L_i];
    END_IF;
END_FOR;

// В режиме антизамерзания обеспечиваем минимальный запрос тепла
IF L_Freeze_Mode_Active AND L_Demand_Power < 20.0 THEN
    L_Demand_Power := 20.0;
END_IF;

IF L_Policy_Degraded THEN
    IF L_Demand_Power > 60.0 THEN
        L_Demand_Power := 60.0;
    END_IF;
END_IF;

fbBoilerCascade(
    VI_Enable := VI_IsActivePLC AND ((L_Demand_Power > GVL_CONSTANTS.C_BOILER_CASCADE_MIN_DEMAND) OR L_Freeze_Mode_Active),
    VI_System_Time_MS := VI_System_Time_MS,
    VI_Boiler_Stop := FALSE,
    VI_DHW_Heating_Demand := VI_DHW_Heating_Demand,
    VI_DHW_Target_Temp := VI_DHW_Target_Temp,
    VI_Target_Supply_Temp := L_Target_Supply_Temp,
    VI_Demand_Power := L_Demand_Power,
    VI_Boiler_Flame_Status := VI_Boiler_Flame_Status,
    VI_Boiler_Error_Status := VI_Boiler_Error_Status,
    VI_Boiler_OT_Online := VI_Boiler_OT_Online,
    VI_Boiler_Modulation := VI_Boiler_Modulation,
    VO_Boiler_Enable => L_Boiler_Request_Enable,
    VO_Boiler_Setpoint => L_Boiler_Request_Setpoint,
    VO_Lead_Boiler => L_Lead_Boiler
);



// ========================================
// OT availability enforcement (no fallback)
// ========================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF NOT VI_Boiler_OT_Online[L_i] OR VI_Boiler_Error_Status[L_i] THEN
        L_Boiler_Request_Enable[L_i] := FALSE;
        L_Boiler_Request_Setpoint[L_i] := 0.0;
    END_IF;
END_FOR;

fbBoilerOpenTherm(
    VI_Enable := L_Boiler_Request_Enable,
    VI_Setpoint := L_Boiler_Request_Setpoint,
    VI_OT_Online := VI_Boiler_OT_Online,
    VI_OT_Error := VI_Boiler_Error_Status,
    VO_OT_Enable => VO_Boiler_OT_Enable,
    VO_OT_Setpoint => VO_Boiler_OT_Setpoint,
    VO_OT_Command_Valid => L_Boiler_OT_Command_Valid
);


// ========================================
// Boiler status normalization
// ========================================
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    // Базовый сброс диагностических флагов котла
    VO_Boiler_Status[L_i].Active := L_Boiler_Request_Enable[L_i];
    VO_Boiler_Status[L_i].Warning := FALSE;
    VO_Boiler_Status[L_i].Error := FALSE;

    // Приоритет причин:
    // 1. Нет канала OpenTherm
    // 2. Котёл вернул ошибку
    // 3. Есть запрос, но нет пламени
    IF NOT VI_Boiler_OT_Online[L_i] THEN
        VO_Boiler_Status[L_i].Error := TRUE;
        VO_Boiler_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_BOILER_OFFLINE);
        L_Any_Subsystem_Degraded := TRUE;
    ELSIF VI_Boiler_Error_Status[L_i] THEN
        VO_Boiler_Status[L_i].Error := TRUE;
        VO_Boiler_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_BOILER_GENERAL_FAULT);
        L_Any_Subsystem_Degraded := TRUE;
    ELSIF L_Boiler_Request_Enable[L_i] AND NOT VI_Boiler_Flame_Status[L_i] THEN
        VO_Boiler_Status[L_i].Warning := TRUE;
        VO_Boiler_Status[L_i].Error_ID := TO_WORD(GVL_CONFIG.ERR_BOILER_NO_FLAME);
        L_Any_Subsystem_Degraded := TRUE;
    ELSE
        VO_Boiler_Status[L_i].Error_ID := 0;
    END_IF;
END_FOR;

// Расчет наработки и остаточного ресурса котлов (ТЗ 2.8)
IF NOT L_Scan_Time_Init THEN
    L_Last_Scan_Time := VI_System_Time_MS;
    L_Scan_Time_Init := TRUE;
END_IF;

L_Delta_MS := (SEL(VI_System_Time_MS >= L_Last_Scan_Time, VI_System_Time_MS - L_Last_Scan_Time, (4294967295 - L_Last_Scan_Time) + VI_System_Time_MS + 1));
IF L_Delta_MS > 1000 THEN
    L_Delta_MS := 1000; // Ограничение дельты для предотвращения скачков после перезагрузки
END_IF;

L_Last_Scan_Time := VI_System_Time_MS;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    VO_Boiler_Status[L_i].Work_Seconds := GVL_Retain.G_Boiler_Work_Seconds[L_i];

    IF VI_Boiler_Flame_Status[L_i] THEN
        GVL_Retain.G_Boiler_Accumulated_MS[L_i] := GVL_Retain.G_Boiler_Accumulated_MS[L_i] + L_Delta_MS;
        IF GVL_Retain.G_Boiler_Accumulated_MS[L_i] >= GVL_CONSTANTS.C_MS_IN_SECOND THEN
            GVL_Retain.G_Boiler_Work_Seconds[L_i] := GVL_Retain.G_Boiler_Work_Seconds[L_i] + (GVL_Retain.G_Boiler_Accumulated_MS[L_i] / 1000);
            GVL_Retain.G_Boiler_Accumulated_MS[L_i] := GVL_Retain.G_Boiler_Accumulated_MS[L_i] MOD 1000;

            // Защита от переполнения (сброс при достижении ~136 лет)
            IF GVL_Retain.G_Boiler_Work_Seconds[L_i] > 4000000000 THEN
                GVL_Retain.G_Boiler_Work_Seconds[L_i] := 0;
            END_IF;

            VO_Boiler_Status[L_i].Work_Seconds := GVL_Retain.G_Boiler_Work_Seconds[L_i];
        END_IF;
    END_IF;

    VO_Boiler_Status[L_i].Work_Hours := TO_REAL(VO_Boiler_Status[L_i].Work_Seconds) / 3600.0;

    L_Boiler_Life[L_i](
        VI_Runtime_Hours := TO_UDINT(VO_Boiler_Status[L_i].Work_Hours),
        VI_Start_Count := 0, // Не считаем пуски для котлов в этой версии
        VI_Nominal_Life := 50000 // 50,000 часов
    );
    VO_Boiler_Status[L_i].Resource_Percent := TO_REAL(L_Boiler_Life[L_i].VO_Remaining_Percent);
    VO_Boiler_Status[L_i].Running := VI_Boiler_Flame_Status[L_i];
END_FOR;
GVL_STATE.G_Heating_Subsystem_Degraded := L_Any_Subsystem_Degraded;

// >>> BULK_SYNC_ANCHOR: FB_Heating_System_Manager <<<

VO_System_OK := FALSE;
VO_System_Warning := FALSE;
VO_System_Critical := FALSE;
VO_Status_Msg := '';
VO_System_Mode := E_System_Operating_Mode.MODE_NORMAL;

CASE VI_System_Severity OF
    E_System_Severity.SEV_NORMAL:
        VO_System_OK := TRUE;
        VO_Status_Msg := 'Система в норме';
        VO_System_Mode := E_System_Operating_Mode.MODE_NORMAL;

    E_System_Severity.SEV_WARNING:
        VO_System_Warning := TRUE;
        VO_System_Mode := E_System_Operating_Mode.MODE_DEGRADED;
        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_WATER_LEAK:
                VO_Status_Msg := 'Предупреждение: протечка воды';
            E_System_Root_Cause.ROOT_CO_WARNING:
                VO_Status_Msg := 'Предупреждение: повышенный CO';
            ELSE
                VO_Status_Msg := 'Предупреждение системы';
        END_CASE;

    E_System_Severity.SEV_DEGRADED:
        VO_System_Warning := TRUE;
        VO_System_Mode := E_System_Operating_Mode.MODE_DEGRADED;
        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_SENSOR_FAULT:
                VO_Status_Msg := 'Деградация: ошибка датчика';
            E_System_Root_Cause.ROOT_IO_OFFLINE:
                VO_Status_Msg := 'Деградация: модуль IO недоступен';
            E_System_Root_Cause.ROOT_COMM_FAULT:
                VO_Status_Msg := 'Деградация: ошибка связи';
            E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
                VO_Status_Msg := 'Деградация: watchdog fault';
            E_System_Root_Cause.ROOT_SUBSYSTEM_FAULT:
                VO_Status_Msg := 'Деградация: ошибка подсистемы';
            ELSE
                VO_Status_Msg := 'Деградация системы';
        END_CASE;

    E_System_Severity.SEV_CRITICAL:
        VO_System_Critical := TRUE;

        IF (VI_Root_Cause = E_System_Root_Cause.ROOT_GAS_LEAK OR
            VI_Root_Cause = E_System_Root_Cause.ROOT_CO_CRITICAL) AND
            VI_Freeze_Risk THEN
            VO_System_Mode := E_System_Operating_Mode.MODE_FREEZE_PROTECTION;
        ELSE
            VO_System_Mode := E_System_Operating_Mode.MODE_SAFE_STOP;
        END_IF;

        CASE VI_Root_Cause OF
            E_System_Root_Cause.ROOT_FIRE:
                VO_Status_Msg := 'АВАРИЯ: ПОЖАР';
            E_System_Root_Cause.ROOT_GAS_LEAK:
                VO_Status_Msg := 'АВАРИЯ: УТЕЧКА ГАЗА';
            E_System_Root_Cause.ROOT_CO_CRITICAL:
                VO_Status_Msg := 'АВАРИЯ: КРИТИЧЕСКИЙ CO';
            E_System_Root_Cause.ROOT_WATCHDOG_FAULT:
                VO_Status_Msg := 'АВАРИЯ: WATCHDOG';
            ELSE
                VO_Status_Msg := 'АВАРИЯ СИСТЕМЫ';
        END_CASE;
END_CASE;
// >>> BULK_SYNC_ANCHOR: FB_State_Manager <<<

VO_Transition_Allowed := TRUE;
VO_Reason := 'OK';

// no-op transition is always allowed
IF VI_Current_Scenario = VI_Target_Scenario THEN
    RETURN;
END_IF;

// emergency can always be entered
IF VI_Target_Scenario = E_SCENARIO_TYPE.SCENARIO_EMERGENCY THEN
    RETURN;
END_IF;

// from NONE, any target is allowed
IF VI_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_NONE THEN
    RETURN;
END_IF;

// emergency exit is restricted
IF VI_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_EMERGENCY THEN
    CASE VI_Target_Scenario OF
        E_SCENARIO_TYPE.SCENARIO_NONE,
        E_SCENARIO_TYPE.SCENARIO_AWAY,
        E_SCENARIO_TYPE.SCENARIO_SLEEP,
        E_SCENARIO_TYPE.SCENARIO_PRESENCE:
            RETURN;
    ELSE
        VO_Transition_Allowed := FALSE;
        VO_Reason := 'Переход из EMERGENCY в данный сценарий запрещён';
        RETURN;
    END_CASE;
END_IF;

// away exit is restricted to safe occupancy contexts
IF VI_Current_Scenario = E_SCENARIO_TYPE.SCENARIO_AWAY THEN
    CASE VI_Target_Scenario OF
        E_SCENARIO_TYPE.SCENARIO_NONE,
        E_SCENARIO_TYPE.SCENARIO_SLEEP,
        E_SCENARIO_TYPE.SCENARIO_PRESENCE,
        E_SCENARIO_TYPE.SCENARIO_EMERGENCY:
            RETURN;
    ELSE
        VO_Transition_Allowed := FALSE;
        VO_Reason := 'Переход из AWAY в данный сценарий запрещён';
        RETURN;
    END_CASE;
END_IF;

// default: allow
RETURN;
// >>> BULK_SYNC_ANCHOR: FB_Scenario_Transition_Guard <<<

VO_Event_Pulse := FALSE;
VO_Event_Code := 0;
VO_Event_Value := 0.0;

// 1. Детекция новых тревог (антидребезг + передний фронт)
T_Debounce_Gas(IN := VI_Gas_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Fire(IN := VI_Fire_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Flood(IN := VI_Flood_Alarm, PT := T#500ms, VI_System_Time_MS := VI_System_Time_MS);
T_Debounce_Security(IN := VI_Security_Alarm, PT := T#100ms, VI_System_Time_MS := VI_System_Time_MS);

R_Trig_Gas(CLK := T_Debounce_Gas.Q);
R_Trig_Fire(CLK := T_Debounce_Fire.Q);
R_Trig_Flood(CLK := T_Debounce_Flood.Q);
R_Trig_Security(CLK := T_Debounce_Security.Q);
R_Trig_First_Fault(CLK := VI_First_Fault_Active);
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    R_Trig_Boiler[L_i](CLK := VI_Boiler_Errors[L_i]);
END_FOR;

// 2. Добавление новых тревог в список (Кольцевой буфер)
L_Pending_Count := 0;
L_Event_Pulse_Latched := FALSE;

IF R_Trig_Gas.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Gas';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Критическая концентрация газа!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Fire.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Fire';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Обнаружено задымление!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Flood.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Flood';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := 'Обнаружена протечка воды!';
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_Security.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Security';
    L_Pending_Alarms[L_Pending_Count].Source_ID := 0;
    L_Pending_Alarms[L_Pending_Count].Message := VI_Security_Msg;
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

IF R_Trig_First_Fault.Q AND L_Pending_Count < 10 THEN
    L_Pending_Count := L_Pending_Count + 1;
    L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
    L_Pending_Alarms[L_Pending_Count].Source := 'Diagnostics';
    L_Pending_Alarms[L_Pending_Count].Source_ID := TO_BYTE(VI_First_Fault_Source);

    CASE VI_First_Fault_Type OF
        1: L_First_Fault_Type_Text := 'IO';
        2: L_First_Fault_Type_Text := 'Sensor';
        3: L_First_Fault_Type_Text := 'Comm';
        4: L_First_Fault_Type_Text := 'Subsystem';
        ELSE L_First_Fault_Type_Text := 'Unknown';
    END_CASE;

    CASE VI_First_Fault_Source OF
        1: L_First_Fault_Source_Text := 'Heating';
        2: L_First_Fault_Source_Text := 'DHW';
        3: L_First_Fault_Source_Text := 'Ventilation';
        4: L_First_Fault_Source_Text := 'Lighting';
        5: L_First_Fault_Source_Text := 'Access';
        ELSE L_First_Fault_Source_Text := 'Unknown';
    END_CASE;

    L_Pending_Alarms[L_Pending_Count].Message := CONCAT('Diagnostics root cause: ', CONCAT(L_First_Fault_Source_Text, CONCAT(' / ', L_First_Fault_Type_Text)));
    L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
    L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
    L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
END_IF;

FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
    IF R_Trig_Boiler[L_j].Q AND L_Pending_Count < 10 THEN
        L_Pending_Count := L_Pending_Count + 1;
        L_Pending_Alarms[L_Pending_Count].Timestamp_MS := VI_System_Time_MS;
        L_Pending_Alarms[L_Pending_Count].Source := 'Boiler';
        L_Pending_Alarms[L_Pending_Count].Source_ID := TO_BYTE(L_j);
        L_Pending_Alarms[L_Pending_Count].Message := CONCAT('Авария котла №', INT_TO_STRING(L_j));
        L_Pending_Alarms[L_Pending_Count].Severity := E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH;
        L_Pending_Alarms[L_Pending_Count].Is_Active := TRUE;
        L_Pending_Alarms[L_Pending_Count].Is_Acknowledged := FALSE;
    END_IF;
END_FOR;



// Обработка очереди новых тревог с учетом приоритетов
FOR L_i := 1 TO L_Pending_Count DO

    L_Target_Slot := 0;

    // 1. Ищем пустой слот
    FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF VO_Alarm_List[L_k].ID = 0 THEN
            L_Target_Slot := L_k;
            EXIT;
        END_IF;
    END_FOR;

    // 2. Ищем квитированную тревогу с наименьшим приоритетом
    IF L_Target_Slot = 0 THEN
        L_Min_Pri := 999;
        FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
            IF VO_Alarm_List[L_k].Is_Acknowledged AND TO_INT(VO_Alarm_List[L_k].Severity) < L_Min_Pri THEN
                L_Min_Pri := TO_INT(VO_Alarm_List[L_k].Severity);
                L_Target_Slot := L_k;
            END_IF;
        END_FOR;
    END_IF;

    // 3. Ищем неквитированную тревогу с наименьшим приоритетом (если он ниже добавляемой)
    IF L_Target_Slot = 0 THEN
        L_Min_Pri := 999;
        FOR L_k := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
            IF TO_INT(VO_Alarm_List[L_k].Severity) < L_Min_Pri AND TO_INT(VO_Alarm_List[L_k].Severity) < TO_INT(L_Pending_Alarms[L_i].Severity) THEN
                L_Min_Pri := TO_INT(VO_Alarm_List[L_k].Severity);
                L_Target_Slot := L_k;
            END_IF;
        END_FOR;
    END_IF;

    IF L_Target_Slot = 0 THEN 
        // Буфер полон критических неквитированных тревог. Не затираем!
        CONTINUE; 
    END_IF;

    VO_Alarm_List[L_Target_Slot] := L_Pending_Alarms[L_i];
    VO_Alarm_List[L_Target_Slot].ID := VIO_Next_Alarm_ID;
    VIO_Next_Alarm_ID := VIO_Next_Alarm_ID + 1;
    IF VIO_Next_Alarm_ID = 0 THEN VIO_Next_Alarm_ID := 1; END_IF;
    IF NOT L_Event_Pulse_Latched THEN
        VO_Event_Pulse := TRUE;
        VO_Event_Code := 1203;
        VO_Event_Value := TO_REAL(VO_Alarm_List[L_Target_Slot].Severity);
        L_Event_Pulse_Latched := TRUE;
    END_IF;
END_FOR;

// 3. Обновление статуса существующих тревог (ушли ли они?)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 THEN
        IF VO_Alarm_List[L_i].Source = 'Gas' THEN VO_Alarm_List[L_i].Is_Active := VI_Gas_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Fire' THEN VO_Alarm_List[L_i].Is_Active := VI_Fire_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Flood' THEN VO_Alarm_List[L_i].Is_Active := VI_Flood_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Security' THEN VO_Alarm_List[L_i].Is_Active := VI_Security_Alarm;
        ELSIF VO_Alarm_List[L_i].Source = 'Diagnostics' THEN VO_Alarm_List[L_i].Is_Active := VI_First_Fault_Active;
        ELSIF VO_Alarm_List[L_i].Source = 'Boiler' THEN 
            IF TO_INT(VO_Alarm_List[L_i].Source_ID) >= 1 AND TO_INT(VO_Alarm_List[L_i].Source_ID) <= GVL_CONSTANTS.C_MAX_BOILERS THEN
                VO_Alarm_List[L_i].Is_Active := VI_Boiler_Errors[TO_INT(VO_Alarm_List[L_i].Source_ID)];
            END_IF;
        END_IF;
    END_IF;
END_FOR;

// 4. Квитирование тревог
IF VI_Acknowledge_All THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
        IF VO_Alarm_List[L_i].ID <> 0 THEN
            VO_Alarm_List[L_i].Is_Acknowledged := TRUE;
        END_IF;
    END_FOR;

    IF NOT L_Event_Pulse_Latched THEN
        VO_Event_Pulse := TRUE;
        VO_Event_Code := 1201;
        VO_Event_Value := TO_REAL(VO_Unacked_Count);
        L_Event_Pulse_Latched := TRUE;
    END_IF;
END_IF;

// 4.5 Автоквитирование некритичных тревог, если они больше не активны
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 AND NOT VO_Alarm_List[L_i].Is_Active AND NOT VO_Alarm_List[L_i].Is_Acknowledged THEN
        IF VO_Alarm_List[L_i].Severity <> E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL THEN
            VO_Alarm_List[L_i].Is_Acknowledged := TRUE;
        END_IF;
    END_IF;
END_FOR;

// 5. Очистка списка (удаление неактивных И квитированных тревог)
// В кольцевом буфере мы просто помечаем слот как пустой (ID = 0), без сдвига массива
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 AND NOT VO_Alarm_List[L_i].Is_Active AND VO_Alarm_List[L_i].Is_Acknowledged THEN
        // Удаляем тревогу
        VO_Alarm_List[L_i].ID := 0;
        IF NOT L_Event_Pulse_Latched THEN
            VO_Event_Pulse := TRUE;
            VO_Event_Code := 1202;
            VO_Event_Value := 0.0;
            L_Event_Pulse_Latched := TRUE;
        END_IF;
    END_IF;
END_FOR;


// 6. Подсчет статистики и формирование глобальных флагов
VO_Global_Critical := FALSE;
VO_Global_Warning := FALSE;
VO_Siren_Active := FALSE;
VO_Active_Count := 0;
VO_Unacked_Count := 0;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALARMS DO
    IF VO_Alarm_List[L_i].ID <> 0 THEN
        IF VO_Alarm_List[L_i].Is_Active THEN
            VO_Active_Count := VO_Active_Count + 1;
        END_IF;

        IF NOT VO_Alarm_List[L_i].Is_Acknowledged THEN
            VO_Unacked_Count := VO_Unacked_Count + 1;

            IF VO_Alarm_List[L_i].Severity = E_ALERT_PRIORITY.ALERT_PRIORITY_CRITICAL THEN
                VO_Global_Critical := TRUE;
                // Сирена работает только для неквитированных критических тревог, если не включен Mute
                IF NOT VI_Mute_Siren THEN
                    VO_Siren_Active := TRUE;
                END_IF;
            ELSIF VO_Alarm_List[L_i].Severity = E_ALERT_PRIORITY.ALERT_PRIORITY_HIGH THEN
                VO_Global_Warning := TRUE;
            END_IF;
        END_IF;
    END_IF;
END_FOR;
// >>> BULK_SYNC_ANCHOR: FB_Alarm_Manager <<<

L_Current_Slot := (VI_Time_Index / (GVL_CONSTANTS.C_MS_IN_MINUTE * 10)) MOD TO_UDINT(GVL_CONSTANTS.C_MAX_PRESENCE_HISTORY); // Слот каждые 10 минут

IF VI_Mode_Record THEN
    // Запись текущего состояния в слот
    GVL_Retain.G_Presence_History[L_Current_Slot] := 0;
    FOR L_i := 1 TO 32 DO
        IF VI_Light_Inputs[L_i] THEN
            GVL_Retain.G_Presence_History[L_Current_Slot] := GVL_Retain.G_Presence_History[L_Current_Slot] OR SHL(WORD#1, L_i-1);
        END_IF;
    END_FOR;
ELSE
    // Воспроизведение из слота
    FOR L_i := 1 TO 32 DO
        VO_Light_Outputs[L_i] := (GVL_Retain.G_Presence_History[L_Current_Slot] AND SHL(WORD#1, L_i-1)) <> 0;
    END_FOR;
END_IF;

L_seed := VI_Seed_Value;
L_Is_Seeded := TRUE;
Seed := TRUE;

IF NOT L_Is_Seeded AND VI_System_Time_MS > 0 THEN
    L_seed := VI_System_Time_MS;
    L_Is_Seeded := TRUE;
END_IF;

L_seed := (C_LCG_MULTIPLIER * L_seed) + C_LCG_INCREMENT;

IF VI_max > VI_min THEN
        L_range := VI_max - VI_min;
        // Используем LREAL для точности и исключения выхода за границу
        L_rand_factor := TO_LREAL(L_seed) / C_LCG_MODULUS;
        Random_Int_Range := VI_min + TO_UDINT(L_rand_factor * TO_LREAL(L_range + 1));

        // Финальная защита от переполнения
        IF Random_Int_Range > VI_max THEN
            Random_Int_Range := VI_max;
        END_IF;
    ELSE
        Random_Int_Range := VI_min;
    END_IF;

// ========================================
// Ventilation policy layer
// ========================================
GVL_STATE.G_Ventilation_IO_Fault := FALSE;
GVL_STATE.G_Ventilation_Subsystem_Degraded := FALSE;
L_Policy_Normal := (VI_System_Mode = E_System_Operating_Mode.MODE_NORMAL);
L_Policy_Safe_Stop := (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
L_Policy_Freeze_Protection := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);

IF NOT VI_IsActivePLC THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
        IF L_i <= GVL_CONSTANTS.C_MAX_SUPPLY_TEMPS THEN
            VO_Heater_Power[L_i] := 0.0;
        END_IF;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 0;
    END_FOR;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: РЕЗЕРВНЫЙ ПЛК';
    RETURN;
END_IF;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        GVL_STATE.G_Ventilation_IO_Fault := TRUE;
        // Переход в безопасное состояние при потере связи (отключение вентиляции)
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
            VO_Supply_Fans[L_j] := 0;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
            VO_Exhaust_Fans[L_j] := 0;
        END_FOR;
        FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
            VO_Heater_Power[L_j] := 0.0;
        END_FOR;
        VO_Status_Msg := 'ОШИБКА: Потеря связи с модулями ввода-вывода';
        RETURN;
    END_IF;
END_FOR;

// =========================
// SYSTEM MODE OVERRIDE
// =========================
// VENT_POLICY_ROUTING_PHASE3_V2
IF L_Policy_Safe_Stop THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Heater_Power[L_i] := 0.0;
    END_FOR;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: ОСТАНОВЛЕНА POLICY SAFE_STOP';
    RETURN;
END_IF;

IF L_Policy_Degraded THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Heater_Power[L_i] := 0.0;
    END_FOR;
    GVL_STATE.G_Ventilation_Subsystem_Degraded := TRUE;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: DEGRADED POLICY';
END_IF;

IF L_Policy_Freeze_Protection THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
        VO_Supply_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := 0;
    END_FOR;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BOILERS DO
        VO_Heater_Power[L_i] := 0.0;
    END_FOR;
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: FREEZE_PROTECTION POLICY (stop)';
    RETURN;
END_IF;

// MODE_FREEZE_PROTECTION пока оставляем на текущей штатной логике

// 1. Определение базовой скорости и целевой температуры по сценарию (ТЗ 7.1)
CASE VI_Current_Scenario OF
    E_SCENARIO_TYPE.SCENARIO_AWAY:
        L_Base_Speed := VI_Config.Scenario_Modes[3].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[3].Target_Temp;
    E_SCENARIO_TYPE.SCENARIO_SLEEP:
        L_Base_Speed := VI_Config.Scenario_Modes[2].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[2].Target_Temp;
    ELSE // PRESENCE, MORNING, EVENING
        L_Base_Speed := VI_Config.Scenario_Modes[1].Base_Fan_Speed;
        L_Target_Temp := VI_Config.Scenario_Modes[1].Target_Temp;
END_CASE;

// 2. Логика управления приточными установками (П-1, П-2, П-3)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_SUPPLY_FANS DO
    // ПИД-регулирование мощности электрического калорифера
    IF L_i <= GVL_CONSTANTS.C_MAX_SUPPLY_TEMPS THEN
        L_PID_Heaters[L_i](
            VI_SetPoint := L_Target_Temp,
            VI_ProcessValue := VI_Supply_Temps[L_i], // Используем датчик температуры после калорифера
            VI_Kp := 4.0, VI_Tn := 120.0, VI_Tv := 0.0,
            VI_Y_Min := 0.0, VI_Y_Max := 100.0, VI_Cycle_Time_S := 1.0,
            VO_Output => VO_Heater_Power[L_i]
        );
    END_IF;

    // Определение скорости приточного вентилятора
    VO_Supply_Fans[L_i] := L_Base_Speed;

    // Обработка действий от Rule Engine
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_RULES DO
        IF VI_Rule_Actions[L_j].Active AND VI_Rule_Actions[L_j].Target_ID = L_i THEN
            IF VI_Rule_Actions[L_j].Action_Type = E_Rule_Action_Type.ACTION_SET_VENTILATION THEN
                VO_Supply_Fans[L_i] := REAL_TO_BYTE(VI_Rule_Actions[L_j].Value);
            END_IF;
        END_IF;
    END_FOR;

    // Requests are operational requests and must not be reported as subsystem degradation.
END_FOR;

// 3. Логика управления вытяжными установками (В-1 .. В-5)
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
    VO_Exhaust_Fans[L_i] := L_Base_Speed;

    // ТЗ 4.0: Логика вытяжки в санузлах
    FOR L_j := 1 TO GVL_CONSTANTS.C_MAX_WET_ZONES DO
        IF VI_Config.wet_zone_to_exhaust_map[L_j] = L_i THEN
            // Включение по свету, выключение с задержкой 5 минут (используем TOF)
            L_Wet_Zone_Timers[L_j](IN := VI_Wet_Zone_Active[L_j], PT := T#5m, VI_System_Time_MS := VI_System_Time_MS);
            IF VI_Wet_Zone_Active[L_j] THEN
                VO_Exhaust_Fans[L_i] := 80; // Повышенная скорость при присутствии
            ELSIF L_Wet_Zone_Timers[L_j].Q THEN
                VO_Exhaust_Fans[L_i] := 50; // Скорость выбега (пока таймер TOF активен)
            END_IF;
        END_IF;
    END_FOR;

    // Requests are operational requests and must not be reported as subsystem degradation.
END_FOR;








// ========================================
// VENT_FINAL_CLAMP
// ========================================
IF L_Policy_Degraded THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_EXHAUST_FANS DO
        VO_Exhaust_Fans[L_i] := MIN(VO_Exhaust_Fans[L_i], VI_Config.Degraded_Exhaust_Limit);
    END_FOR;
END_IF;

// 4. Формирование статусного сообщения
IF L_Policy_Safe_Stop THEN
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: ОСТАНОВЛЕНА POLICY SAFE_STOP';
ELSIF L_Policy_Freeze_Protection THEN
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: FREEZE_PROTECTION POLICY (stop)';
ELSIF L_Policy_Degraded THEN
    VO_Status_Msg := 'ВЕНТИЛЯЦИЯ: DEGRADED POLICY';
ELSE
    VO_Status_Msg := 'Вентиляция работает в штатном режиме';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Ventilation_System_Manager <<<

// 0. Сброс статистики
IF VI_Reset_Stats THEN
    VIO_Health_Data.Starts_Count := 0;
    VIO_Health_Data.Sample_Count := 0;
    VIO_Health_Data.Current_Sum := 0.0;
    VIO_Health_Data.Avg_Start_Current := 0.0;
    VIO_Health_Data.Health_Score := 100;
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := '';
    VIO_Health_Data.Last_Start_Current := 0.0;
    VIO_Health_Data.Total_Runtime_Hours := 0;
    L_Accumulated_MS := 0;
END_IF;

// 1. Счётчик пусков и замер пускового тока
IF VI_Is_Running AND NOT L_Prev_Running THEN
    VIO_Health_Data.Starts_Count := VIO_Health_Data.Starts_Count + 1;
    VIO_Health_Data.Last_Start_Current := VI_Current_Value;
    L_Start_Time := VI_System_Time_MS;
    L_Last_Calc_Time := VI_System_Time_MS;

    // Обновление среднего пускового тока
    VIO_Health_Data.Sample_Count := VIO_Health_Data.Sample_Count + 1;
    VIO_Health_Data.Current_Sum := VIO_Health_Data.Current_Sum + VI_Current_Value;
    VIO_Health_Data.Avg_Start_Current := VIO_Health_Data.Current_Sum / UDINT_TO_REAL(VIO_Health_Data.Sample_Count);

    // 2. Анализ отклонения пускового тока (п. 12.1 ТЗ)
    IF VI_Current_Value > (VI_Nominal_Value * 1.5) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 5, 100));
    ELSIF VI_Current_Value > (VI_Nominal_Value * 1.2) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
    ELSIF VI_Current_Value < (VI_Nominal_Value * 0.5) THEN
        VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 2, 100));
    END_IF;
END_IF;

// 3. Анализ рабочего тока и наработки
IF VI_Is_Running THEN
    L_Elapsed_MS := (VI_System_Time_MS - L_Last_Calc_Time);
    L_Accumulated_MS := L_Accumulated_MS + L_Elapsed_MS;
    L_Last_Calc_Time := VI_System_Time_MS;

    // Обновляем наработку каждый час (3600000 мс)
    IF L_Accumulated_MS >= 3600000 THEN
        VIO_Health_Data.Total_Runtime_Hours := VIO_Health_Data.Total_Runtime_Hours + 1;
        L_Accumulated_MS := L_Accumulated_MS - 3600000;

        // Естественный износ: -1% здоровья каждые 1000 часов
        IF (VIO_Health_Data.Total_Runtime_Hours MOD 1000) = 0 THEN
            VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
        END_IF;

        // Анализ рабочего тока (после пускового режима)
        IF (VI_System_Time_MS - L_Start_Time) > 10000 THEN // 10 секунд после пуска
            IF VI_Current_Value > (VI_Nominal_Value * 1.1) THEN
                // Повышенный рабочий ток - ускоренный износ (-1% в час)
                VIO_Health_Data.Health_Score := TO_BYTE(LIMIT(0, TO_INT(VIO_Health_Data.Health_Score) - 1, 100));
            END_IF;
        END_IF;
    END_IF;
END_IF;

// 4. Генерация предупреждения
IF VIO_Health_Data.Health_Score < 20 THEN
    VIO_Health_Data.Maintenance_Required := TRUE;
    VIO_Health_Data.Warning_Message := 'Критический износ: проверьте механику';
ELSIF VIO_Health_Data.Health_Score < 60 THEN
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := 'Предупреждение: повышенное трение';
ELSE
    VIO_Health_Data.Maintenance_Required := FALSE;
    VIO_Health_Data.Warning_Message := 'В норме';
END_IF;

L_Prev_Running := VI_Is_Running;

IF VI_Value >= VI_Min_Valid AND VI_Value <= VI_Max_Valid THEN
    VO_Error := FALSE;
    VO_Value := VI_Value;
    L_Last_Good_Value := VI_Value;
    L_First_Valid := TRUE;
ELSE
    VO_Error := TRUE;
    IF VI_Fallback_Mode = 1 OR NOT L_First_Valid THEN
        VO_Value := VI_Default_Value;
    ELSE
        VO_Value := L_Last_Good_Value;
    END_IF;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Analog_Validator <<<

// Вычисление времени цикла
IF L_Last_Time = 0 THEN
    L_Last_Time := VI_System_Time_MS;
    L_Cycle_Time_S := 1.0;
ELSE
    L_Cycle_Time_S := UDINT_TO_REAL((SEL(VI_System_Time_MS >= L_Last_Time, VI_System_Time_MS - L_Last_Time, (4294967295 - L_Last_Time) + VI_System_Time_MS + 1))) / 1000.0;
    L_Last_Time := VI_System_Time_MS;
END_IF;
IF L_Cycle_Time_S <= 0.0 THEN L_Cycle_Time_S := 0.01; END_IF;

// 1. Определение активного тарифа
IF VI_Tariff.Enabled THEN
    IF VI_Tariff.Night_Start_Hour > VI_Tariff.Night_End_Hour THEN
        // Переход через полночь (например, 23:00 - 07:00)
        L_Is_Night := (VI_Current_Hour >= VI_Tariff.Night_Start_Hour) OR (VI_Current_Hour < VI_Tariff.Night_End_Hour);
    ELSE
        // В пределах одного дня
        L_Is_Night := (VI_Current_Hour >= VI_Tariff.Night_Start_Hour) AND (VI_Current_Hour < VI_Tariff.Night_End_Hour);
    END_IF;
ELSE
    L_Is_Night := FALSE;
END_IF;

// 2. Расчет эффективной уставки
VO_Effective_Setpoint := VI_Config.design_temp;
IF L_Is_Night THEN
    VO_Effective_Setpoint := VO_Effective_Setpoint + VI_Tariff.Boost_Delta;
END_IF;

// 3. ПИД-регулирование
L_PID(
    VI_SetPoint := VO_Effective_Setpoint,
    VI_ProcessValue := VI_Current_Temp,
    VI_Kp := VI_Config.pid_kp,
    VI_Tn := 300.0,
    VI_Tv := 0.0,
    VI_Y_Min := 0.0,
    VI_Y_Max := 100.0,
    VI_Cycle_Time_S := L_Cycle_Time_S,
    VO_Output => VO_Valve_Pos
);

// 4. ШИМ-модуляция для термоэлектрического привода
IF VI_Config.pwm_period_s > 0 THEN
    L_PWM_Period_MS := TO_UDINT(VI_Config.pwm_period_s) * 1000;
ELSE
    L_PWM_Period_MS := 600000; // 10 минут
END_IF;

L_Current_Phase_MS := (SEL(VI_System_Time_MS >= L_PWM_Start_Time, VI_System_Time_MS - L_PWM_Start_Time, (4294967295 - L_PWM_Start_Time) + VI_System_Time_MS + 1));
IF L_Current_Phase_MS >= L_PWM_Period_MS THEN
    L_PWM_Start_Time := VI_System_Time_MS - (L_Current_Phase_MS - L_PWM_Period_MS); // Сохраняем остаток для точности
    L_Current_Phase_MS := (SEL(VI_System_Time_MS >= L_PWM_Start_Time, VI_System_Time_MS - L_PWM_Start_Time, (4294967295 - L_PWM_Start_Time) + VI_System_Time_MS + 1));
END_IF;

L_PWM_Duty_MS := TO_UDINT((VO_Valve_Pos / 100.0) * TO_REAL(L_PWM_Period_MS));

IF VI_IsActivePLC THEN
    VO_Pump_Run := (VO_Valve_Pos > 5.0);

    IF VO_Valve_Pos >= 100.0 THEN
        VO_Valve_Bool := TRUE;
    ELSIF VO_Valve_Pos <= 0.0 THEN
        VO_Valve_Bool := FALSE;
    ELSE
        VO_Valve_Bool := (L_Current_Phase_MS <= L_PWM_Duty_MS);
    END_IF;
ELSE
    VO_Pump_Run := FALSE;
    VO_Valve_Bool := FALSE;
END_IF;

IF NOT L_Initialized THEN
    L_Initialized := TRUE;
    L_Last_Call_MS := VI_System_Time_MS;
    VO_Cycle_DT_MS := 0;
    VO_Watchdog_Fault := FALSE;
    VO_Alive := TRUE;
    RETURN;
END_IF;

// Measure real time gap between successive calls
L_DT_MS := (SEL(VI_System_Time_MS >= L_Last_Call_MS, VI_System_Time_MS - L_Last_Call_MS, (4294967295 - L_Last_Call_MS) + VI_System_Time_MS + 1));
VO_Cycle_DT_MS := L_DT_MS;

// Fault if the task/cycle resumed after an abnormal pause
VO_Watchdog_Fault := (L_DT_MS > VI_Timeout_MS);
VO_Alive := NOT VO_Watchdog_Fault;

// Store current timestamp for next cycle
L_Last_Call_MS := VI_System_Time_MS;
// >>> BULK_SYNC_ANCHOR: FB_Watchdog <<<

// >>> SYNC_TEST_MARKER_001 <<<


IF NOT VI_IsActivePLC THEN RETURN; END_IF;


GVL_STATE.G_DHW_IO_Fault := FALSE;
GVL_STATE.G_DHW_Sensor_Fault := FALSE;
GVL_STATE.G_DHW_Subsystem_Degraded := FALSE;

IF VI_Emergency_Stop THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    VO_Status.Warning := FALSE;
    VO_Status.Error := TRUE;
    VO_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_DHW_IO_OFFLINE); // временно используем общий аварийный код до детализации safety-кодов
    VO_Status.Heating_Pump_On := FALSE;
    VO_Status.Circ_Pump_On := FALSE;
    RETURN;
END_IF;

// Фиксация текущего времени
L_Current_TOD := VI_Current_TOD;

// ========================================
// DHW POLICY LAYER
// ========================================
L_Policy_Safe_Stop := (VI_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP);
L_Policy_Freeze_Protection := (VI_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);
L_Policy_Degraded := (VI_System_Mode = E_System_Operating_Mode.MODE_DEGRADED);
L_Target_Temp_Adjusted := VI_Config.Target_Temp;
IF L_Policy_Degraded THEN
    L_Target_Temp_Adjusted := VI_Config.Target_Temp - VI_Config.Degraded_Target_Delta;
END_IF;

// ========================================
// DHW POLICY OVERRIDE
// ========================================
IF L_Policy_Safe_Stop THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    RETURN;
END_IF;

IF L_Policy_Freeze_Protection THEN
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    RETURN;
END_IF;

// Сброс признака выполнения термодезинфекции при смене дня.
IF L_Last_Legionella_Day <> VI_Current_Day_Of_Week THEN
    L_Legionella_Done_Today := FALSE;
    L_Last_Legionella_Day := VI_Current_Day_Of_Week;
END_IF;

// Базовый сброс незащёлкнутых статусных флагов на текущий цикл.
// Критические ошибки ниже могут зафиксироваться и завершить выполнение через RETURN.
VO_Status.Warning := FALSE;
VO_Status.Error := FALSE;
VO_Status.Error_ID := 0;

// Сброс ошибок
IF VI_Reset_Errors THEN
    L_Error_Latched := FALSE;
    L_Error_ID_Latched := 0;
END_IF;

// Проверка связи с модулями ввода-вывода
FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MODULES DO
    IF NOT VI_IO_Modules_Online[L_i] THEN
        L_Error_Latched := TRUE;
        GVL_STATE.G_DHW_IO_Fault := TRUE;
        L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_IO_OFFLINE); // Потеря связи с модулями ввода-вывода
    END_IF;
END_FOR;

// 1. Обработка неисправностей датчиков и сервисных режимов (ТЗ 7.0)
fbTempValidator(
    VI_Value := VI_Temp,
    VI_Min_Valid := 0.0,
    VI_Max_Valid := 100.0,
    VI_Fallback_Mode := 0,
    VI_Default_Value := 55.0
);

fbPressValidator(
    VI_Value := VI_Pressure,
    VI_Min_Valid := 0.0,
    VI_Max_Valid := 10.0,
    VI_Fallback_Mode := 0
);

VO_Status.Temp := fbTempValidator.VO_Value;
VO_Status.Pressure := fbPressValidator.VO_Value;

// Сохраняем последнее достоверное значение температуры ГВС.
// Используется только для диагностики/сервиса, не для fallback-управления.
IF NOT fbTempValidator.VO_Error THEN
    L_Last_Good_Temp := VO_Status.Temp;
END_IF;

IF fbTempValidator.VO_Error THEN
    GVL_STATE.G_DHW_Sensor_Fault := TRUE;
    L_Error_Latched := TRUE;
    L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_TEMP_SENSOR_FAULT); // Критическая ошибка датчика температуры
ELSIF (VO_Status.Pressure < 1.0 OR VO_Status.Pressure > 4.0) AND NOT fbPressValidator.VO_Error THEN
    L_Error_Latched := TRUE;
    L_Error_ID_Latched := TO_WORD(GVL_CONFIG.ERR_DHW_PRESSURE_OUT_OF_RANGE); // Давление вне нормы
END_IF;

IF L_Error_Latched THEN
    // Критическая ошибка: переход в безопасное состояние с полной остановкой насосов.
    VO_Heating_Pump := FALSE;
    VO_Circ_Pump := FALSE;
    VO_Status.Warning := FALSE;
    VO_Status.Error := TRUE;
    VO_Status.Error_ID := L_Error_ID_Latched;
    VO_Status.Heating_Pump_On := FALSE;
    VO_Status.Circ_Pump_On := FALSE;
    RETURN;
END_IF;

// Ошибка датчика давления не останавливает ГВС,
// но переводит подсистему в режим предупреждения (degraded mode).
IF fbPressValidator.VO_Error THEN
    GVL_STATE.G_DHW_Sensor_Fault := TRUE;
    GVL_STATE.G_DHW_Subsystem_Degraded := TRUE;
    VO_Status.Warning := TRUE;
    VO_Status.Error := FALSE;
    VO_Status.Error_ID := TO_WORD(GVL_CONFIG.ERR_DHW_PRESSURE_SENSOR_FAULT);
END_IF;

// 2. Логика поддержания температуры воды в бойлере (Нагрев)
// На этом этапе FB уже выполняется только на активном ПЛК.

// Термическая дезинфекция (Легионелла)
IF VI_Config.Anti_Legionella_Enabled
   AND (VI_Current_Day_Of_Week = VI_Config.Anti_Legionella_Day)
   AND (L_Current_TOD >= TOD#02:00)
   AND (L_Current_TOD <= TOD#04:00)
   AND NOT L_Legionella_Done_Today THEN
    L_Legionella_Active := TRUE;
ELSE
    L_Legionella_Active := FALSE;
END_IF;

L_Legionella_Timer(IN := L_Legionella_Active AND VO_Status.Temp >= 70.0, PT := T#30m, VI_System_Time_MS := VI_System_Time_MS);
IF L_Legionella_Timer.Q THEN
    L_Legionella_Active := FALSE; // Дезинфекция завершена
    L_Legionella_Done_Today := TRUE; // Повторно в те же сутки не запускать
END_IF;

// Двухпозиционное регулирование с гистерезисом
IF L_Legionella_Active THEN
    IF VO_Status.Temp < 70.0 THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > 72.0 THEN
        VO_Heating_Pump := FALSE;
    END_IF;
ELSE
    IF VO_Status.Temp < (L_Target_Temp_Adjusted - VI_Config.Hysteresis) THEN
        VO_Heating_Pump := TRUE;
    ELSIF VO_Status.Temp > (L_Target_Temp_Adjusted + VI_Config.Hysteresis) THEN
        VO_Heating_Pump := FALSE;
    END_IF;
END_IF;

// 3. Управление циркуляционным насосом ГВС по расписанию
// Рециркуляция обеспечивает мгновенное наличие горячей воды у потребителя
VO_Circ_Pump := SEL(VI_Config.Circulation_Schedule_Enabled AND NOT (VI_Config.Night_Mode_Enabled AND (L_Current_TOD < VI_Config.Circulation_Start OR L_Current_TOD > VI_Config.Circulation_End)), FALSE, TRUE);

// Формирование статусных данных для визуализации.
// К этому моменту статус уже консистентен:
// - Error = критическая ошибка с остановкой ГВС
// - Warning = деградация без остановки
VO_Status.Heating_Pump_On := VO_Heating_Pump;
VO_Status.Circ_Pump_On := VO_Circ_Pump;

// >>> BULK_SYNC_ANCHOR: FB_DHW_Manager <<<

IF VI_Trigger_Event THEN
    L_Snapshot_Buffer[L_Write_Idx] := VI_Current_State;
    L_Snapshot_Buffer[L_Write_Idx].timestamp_ms := VI_System_Time_MS;

    // NOTE:
    // ST_State_Snapshot no longer contains trigger_event_code in live project.
    // VI_Event_Code is reserved for future snapshot metadata extension.

    L_Write_Idx := (L_Write_Idx MOD GVL_CONSTANTS.C_MAX_STATE_SNAPSHOTS) + 1;
    VO_Snapshot_Saved := TRUE;
ELSE
    VO_Snapshot_Saved := FALSE;
END_IF;

// === DELTA TIME ===
IF VI_System_Time_MS >= L_Last_Time THEN
    L_Delta_MS := VI_System_Time_MS - L_Last_Time;
ELSE
    // overflow
    L_Delta_MS := (4294967295 - L_Last_Time) + VI_System_Time_MS + 1;
END_IF;

L_Last_Time := VI_System_Time_MS;

// === START COUNT ===
IF VI_Device_Active AND NOT L_Prev_State THEN
    VIO_Status.start_count := VIO_Status.start_count + 1;
END_IF;

L_Prev_State := VI_Device_Active;

// === RUNTIME ACCUMULATION ===
IF VI_Device_Active THEN
    L_Runtime_Accum_MS := L_Runtime_Accum_MS + L_Delta_MS;

    WHILE L_Runtime_Accum_MS >= 3600000 DO
        VIO_Status.runtime_hours := VIO_Status.runtime_hours + 1;
        L_Runtime_Accum_MS := L_Runtime_Accum_MS - 3600000;
    END_WHILE;
END_IF;

// === BASIC LIFETIME ESTIMATION ===
IF VI_Nominal_Hours > 0 THEN
    IF VIO_Status.runtime_hours >= VI_Nominal_Hours THEN
        VIO_Status.remaining_hours := 0;
        VIO_Status.remaining_percent := 0;
    ELSE
        VIO_Status.remaining_hours := VI_Nominal_Hours - VIO_Status.runtime_hours;
        L_Remaining_Percent_UDINT := (VIO_Status.remaining_hours * 100) / VI_Nominal_Hours;

        IF L_Remaining_Percent_UDINT > 100 THEN
            L_Remaining_Percent_UDINT := 100;
        END_IF;

        VIO_Status.remaining_percent := UDINT_TO_BYTE(L_Remaining_Percent_UDINT);
    END_IF;
ELSE
    VIO_Status.remaining_hours := 0;
    VIO_Status.remaining_percent := 0;
END_IF;

VIO_Status.maintenance_required := VIO_Status.remaining_percent <= GVL_Lifetime.G_Maintenance_Threshold_Percent;

// === BASIC FLAGS ===
VIO_Status.device_id := VI_Device_ID;
VIO_Status.last_calc_timestamp := VI_System_Time_MS;

// Initialize variables
H0 := 16#67452301;
H1 := 16#EFCDAB89;
H2 := 16#98BADCFE;
H3 := 16#10325476;
H4 := 16#C3D2E1F0;

// Pre-processing
FOR i := 0 TO Length - 1 DO
    PaddedData[i] := Data[i];
END_FOR;

// Append the bit '1' to the message
PaddedData[Length] := 16#80;

// Append 0 <= k < 512 bits '0', such that the resulting message length in bits
// is congruent to -64 ≡ 448 (mod 512)
PaddedLength := Length + 1;
WHILE (PaddedLength MOD 64) <> 56 DO
    PaddedData[PaddedLength] := 0;
    PaddedLength := PaddedLength + 1;
END_WHILE;

// Append length of message (before pre-processing), in bits, as 64-bit big-endian integer
// Since our message is small (max 127 bytes), we only need the lower 32 bits
Temp := TO_DWORD(Length * 8);
PaddedData[PaddedLength] := 0;
PaddedData[PaddedLength+1] := 0;
PaddedData[PaddedLength+2] := 0;
PaddedData[PaddedLength+3] := 0;
PaddedData[PaddedLength+4] := TO_BYTE(SHR(Temp, 24));
PaddedData[PaddedLength+5] := TO_BYTE(SHR(Temp, 16));
PaddedData[PaddedLength+6] := TO_BYTE(SHR(Temp, 8));
PaddedData[PaddedLength+7] := TO_BYTE(Temp);
PaddedLength := PaddedLength + 8;

NumBlocks := PaddedLength / 64;

// Process the message in successive 512-bit chunks
FOR i := 0 TO NumBlocks - 1 DO
    BlockOffset := i * 64;

    // Break chunk into sixteen 32-bit big-endian words w[i], 0 <= i <= 15
    FOR j := 0 TO 15 DO
        W[j] := SHL(TO_DWORD(PaddedData[BlockOffset + j*4]), 24) OR
                SHL(TO_DWORD(PaddedData[BlockOffset + j*4 + 1]), 16) OR
                SHL(TO_DWORD(PaddedData[BlockOffset + j*4 + 2]), 8) OR
                TO_DWORD(PaddedData[BlockOffset + j*4 + 3]);
    END_FOR;

    // Message schedule: extend the sixteen 32-bit words into eighty 32-bit words
    FOR j := 16 TO 79 DO
        Temp := W[j-3] XOR W[j-8] XOR W[j-14] XOR W[j-16];
        W[j] := SHL(Temp, 1) OR SHR(Temp, 31); // Left rotate by 1
    END_FOR;

    // Initialize hash value for this chunk
    A := H0;
    B := H1;
    C := H2;
    D := H3;
    E := H4;

    // Main loop
    FOR j := 0 TO 79 DO
        IF j <= 19 THEN
            F := (B AND C) OR ((NOT B) AND D);
            K := 16#5A827999;
        ELSIF j <= 39 THEN
            F := B XOR C XOR D;
            K := 16#6ED9EBA1;
        ELSIF j <= 59 THEN
            F := (B AND C) OR (B AND D) OR (C AND D);
            K := 16#8F1BBCDC;
        ELSE
            F := B XOR C XOR D;
            K := 16#CA62C1D6;
        END_IF;

        Temp := (SHL(A, 5) OR SHR(A, 27)) + F + E + K + W[j];
        E := D;
        D := C;
        C := SHL(B, 30) OR SHR(B, 2);
        B := A;
        A := Temp;
    END_FOR;

    // Add this chunk's hash to result so far
    H0 := H0 + A;
    H1 := H1 + B;
    H2 := H2 + C;
    H3 := H3 + D;
    H4 := H4 + E;
END_FOR;

// Produce the final hash value (big-endian)
Hash[0] := TO_BYTE(SHR(H0, 24)); Hash[1] := TO_BYTE(SHR(H0, 16)); Hash[2] := TO_BYTE(SHR(H0, 8)); Hash[3] := TO_BYTE(H0);
Hash[4] := TO_BYTE(SHR(H1, 24)); Hash[5] := TO_BYTE(SHR(H1, 16)); Hash[6] := TO_BYTE(SHR(H1, 8)); Hash[7] := TO_BYTE(H1);
Hash[8] := TO_BYTE(SHR(H2, 24)); Hash[9] := TO_BYTE(SHR(H2, 16)); Hash[10] := TO_BYTE(SHR(H2, 8)); Hash[11] := TO_BYTE(H2);
Hash[12] := TO_BYTE(SHR(H3, 24)); Hash[13] := TO_BYTE(SHR(H3, 16)); Hash[14] := TO_BYTE(SHR(H3, 8)); Hash[15] := TO_BYTE(H3);
Hash[16] := TO_BYTE(SHR(H4, 24)); Hash[17] := TO_BYTE(SHR(H4, 16)); Hash[18] := TO_BYTE(SHR(H4, 8)); Hash[19] := TO_BYTE(H4);

// === BUILD STRUCT FROM STATE ===
// === NVRAM SNAPSHOT VIA STRUCT ADAPTER ===
VIO_PersistStruct.System_Mode := GVL_STATE.G_System_Mode;

VIO_PersistStruct.Safety_Gas_Latched := GVL_STATE.G_Safety_Gas_Latched;
VIO_PersistStruct.Safety_Smoke_Latched := GVL_STATE.G_Safety_Smoke_Latched;
VIO_PersistStruct.Safety_Leak_Latched := GVL_STATE.G_Safety_Leak_Latched;

VIO_PersistStruct.DHW_Heating_Pump := GVL_STATE.G_DHW_Heating_Pump;
VIO_PersistStruct.Valid := TRUE;

// mirror to legacy persistent variables
GVL_PERSISTENT.P_System_Mode := VIO_PersistStruct.System_Mode;

GVL_PERSISTENT.P_Safety_Gas_Latched := VIO_PersistStruct.Safety_Gas_Latched;
GVL_PERSISTENT.P_Safety_Smoke_Latched := VIO_PersistStruct.Safety_Smoke_Latched;
GVL_PERSISTENT.P_Safety_Leak_Latched := VIO_PersistStruct.Safety_Leak_Latched;

GVL_PERSISTENT.P_DHW_Heating_Active := VIO_PersistStruct.DHW_Heating_Pump;
GVL_PERSISTENT.P_Valid := VIO_PersistStruct.Valid;

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

CASE L_State OF
    0: // Ожидание
        VO_Test_Active := FALSE;
        L_Need_Test := FALSE;

        // Поиск клапана, которому нужен тест (раз в неделю)
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
            IF VI_Config[L_i].enabled AND ((VI_System_Time_MS - L_Last_Test_Time[L_i]) > (VI_Config[L_i].test_interval_days * 86400000)) THEN
                L_Current_Valve := L_i;
                L_Need_Test := TRUE;
                EXIT;
            END_IF;
        END_FOR;

        IF L_Need_Test THEN
            L_State := 1;
            L_Test_Start_Time := VI_System_Time_MS;
            VO_Test_Active := TRUE;
            VO_Current_Valve := L_Current_Valve;
            VO_Valve_Cmd[L_Current_Valve] := TRUE; // Открываем
            VO_Status_Msg := CONCAT('ТЕСТ КЛАПАНА ', INT_TO_STRING(L_Current_Valve));
            VO_Test_Results[L_Current_Valve] := TRUE; // Сброс результата
        END_IF;

    1: // Тестирование (ожидание открытия)
        L_Elapsed_Time := (VI_System_Time_MS - L_Test_Start_Time);

        IF VI_Valve_End_Switches[L_Current_Valve] THEN
            // Концевик сработал до истечения таймаута
            // Проверка тока
            IF ABS(VI_Valve_Currents[L_Current_Valve] - VI_Config[L_Current_Valve].Nominal_Current) > (VI_Config[L_Current_Valve].Nominal_Current * 0.2) THEN
                VO_Test_Results[L_Current_Valve] := FALSE; // Ошибка по току
            END_IF;

            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := VO_Test_Results[L_Current_Valve];

            VO_Valve_Cmd[L_Current_Valve] := FALSE; // Закрываем
            L_Test_Start_Time := VI_System_Time_MS; // Перезапускаем таймер для проверки закрытия
            L_State := 2;
        ELSIF L_Elapsed_Time > TO_UDINT(VI_Config[L_Current_Valve].nominal_close_time_sec * 1000.0) THEN
            // Таймаут открытия (заклинивание)
            VO_Test_Results[L_Current_Valve] := FALSE; 
            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := FALSE;
            VO_Status_Msg := CONCAT('ОШИБКА: ЗАКЛИНИВАНИЕ КЛАПАНА ', INT_TO_STRING(L_Current_Valve));

            VO_Valve_Cmd[L_Current_Valve] := FALSE; // Закрываем
            L_Test_Start_Time := VI_System_Time_MS; // Перезапускаем таймер
            L_State := 2;
        END_IF;

    2: // Ожидание закрытия
        L_Elapsed_Time := (VI_System_Time_MS - L_Test_Start_Time);

        IF NOT VI_Valve_End_Switches[L_Current_Valve] THEN
            // Концевик разомкнулся (клапан закрыт)
            L_Last_Test_Time[L_Current_Valve] := VI_System_Time_MS;
            L_State := 0;
            IF VO_Test_Results[L_Current_Valve] THEN
                VO_Status_Msg := 'ТЕСТ ЗАВЕРШЕН УСПЕШНО';
            END_IF;
        ELSIF L_Elapsed_Time > TO_UDINT(VI_Config[L_Current_Valve].nominal_close_time_sec * 1000.0) THEN
            // Таймаут закрытия (заклинивание)
            VO_Test_Results[L_Current_Valve] := FALSE; 
            GVL_Retain.G_Valve_Test_Results[L_Current_Valve] := FALSE;
            VO_Status_Msg := CONCAT('ОШИБКА: НЕ ЗАКРЫЛСЯ КЛАПАН ', INT_TO_STRING(L_Current_Valve));

            L_Last_Test_Time[L_Current_Valve] := VI_System_Time_MS;
            L_State := 0;
        END_IF;
END_CASE;

IF NOT VI_IsActivePLC THEN RETURN; END_IF;

L_Any_Leak := FALSE;
L_Any_Warning := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_FLOOD_SENSORS DO
    L_Sensor_Timers[L_i](
        IN := VI_Sensors[L_i],
        PT := TO_TIME(VI_Config.min_duration_ms + VI_Config.warning_duration_ms),
        VI_System_Time_MS := VI_System_Time_MS
    );

    IF L_Sensor_Timers[L_i].ET >= TO_TIME(VI_Config.min_duration_ms) THEN
        L_Any_Warning := TRUE;

        IF L_Sensor_Timers[L_i].Q THEN
            L_Any_Leak := TRUE;
        END_IF;
    END_IF;
END_FOR;

// Health signals
VO_Leak_Detected := L_Any_Leak;
VO_Leak_Warning_Level := L_Any_Warning;

// Status
IF L_Any_Leak THEN
    VO_Status_Msg := 'АВАРИЯ: ПРОТЕЧКА ВОДЫ.';
ELSIF L_Any_Warning THEN
    VO_Status_Msg := 'ПРЕДУПРЕЖДЕНИЕ: ОБНАРУЖЕНА ВОДА.';
ELSE
    VO_Status_Msg := 'Система контроля протечек в норме';
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Water_Leakage_Manager <<<

L_Elapsed := (SEL(VI_System_Time >= VI_Start_Time, VI_System_Time - VI_Start_Time, (4294967295 - VI_Start_Time) + VI_System_Time + 1));

IF L_Elapsed >= VI_Duration OR VI_Duration = 0 THEN
    VO_Current_Value := VI_End_Value;
    VO_Transition_Done := TRUE;
ELSE
    L_Progress := UDINT_TO_REAL(L_Elapsed) / UDINT_TO_REAL(VI_Duration);
    VO_Current_Value := VI_Start_Value + (VI_End_Value - VI_Start_Value) * L_Progress;
    VO_Transition_Done := FALSE;
END_IF;

// ==============================================================================
// Блок таймера задержки выключения (System Timer TOF)
// Назначение:
// - Замена стандартного TOF для обеспечения точной выдержки времени,
//   независимой от времени цикла ПЛК, с использованием единого системного времени.
// ==============================================================================



IF IN THEN
    Q := TRUE;
    ET := T#0s;
    L_Running := FALSE;
ELSE
    IF L_Prev_IN THEN
        L_Start_Time := VI_System_Time_MS;
        L_Running := TRUE;
        ET := T#0s;
    END_IF;

    IF L_Running THEN
        // Обработка переполнения UDINT (примерно 49 дней)
        ET := TO_TIME((SEL(VI_System_Time_MS >= L_Start_Time, VI_System_Time_MS - L_Start_Time, (4294967295 - L_Start_Time) + VI_System_Time_MS + 1)));

        IF ET >= PT THEN
            Q := FALSE;
            ET := PT;
            L_Running := FALSE;
        ELSE
            Q := TRUE;
        END_IF;
    END_IF;
END_IF;

L_Prev_IN := IN;

// Периодическая синхронизация (каждые 5 секунд)
L_Elapsed_Time := (SEL(VI_System_Time_MS >= L_Last_Sync_Time, VI_System_Time_MS - L_Last_Sync_Time, (4294967295 - L_Last_Sync_Time) + VI_System_Time_MS + 1));

IF L_Elapsed_Time > 5000 THEN
    L_Periodic_Sync_Req := TRUE;
    L_Last_Sync_Time := VI_System_Time_MS;
ELSE
    L_Periodic_Sync_Req := FALSE;
END_IF;

// State Replication Logic
// Синхронизация состояния между ПЛК (ТЗ 8.2)
IF (VI_Sync_Req OR L_Periodic_Sync_Req) AND NOT L_Sync_In_Progress THEN
    L_Sync_In_Progress := TRUE;

    // Разрешение конфликтов на основе версии состояния
    IF VI_Remote_State.Version > VI_Local_State.Version THEN
        VO_Synced_State := VI_Remote_State;
        VO_State_Updated := TRUE;
    ELSIF VI_Remote_State.Version = VI_Local_State.Version THEN
        // Если версии равны, приоритет у ведущего ПЛК
        IF VI_Local_Role = E_PLC_ROLE.ROLE_STANDBY THEN
            VO_Synced_State := VI_Remote_State;
            VO_State_Updated := TRUE;
        ELSE
            VO_Synced_State := VI_Local_State;
            VO_State_Updated := FALSE;
        END_IF;
    ELSE
        VO_Synced_State := VI_Local_State;
        VO_State_Updated := FALSE;
    END_IF;
ELSIF NOT (VI_Sync_Req OR L_Periodic_Sync_Req) THEN
    L_Sync_In_Progress := FALSE;
    VO_State_Updated := FALSE;
    VO_Synced_State := VI_Local_State;
END_IF;

// Отправка уведомлений в Telegram (ТЗ 10.2)
VO_Send_Telegram := FALSE;
IF VI_Fire_Alarm_Active AND NOT L_Prev_Fire THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! ПОЖАРНАЯ ТРЕВОГА!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Gas_Alarm_Active AND NOT L_Prev_Gas THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! УТЕЧКА ГАЗА!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Flood_Alarm_Active AND NOT L_Prev_Flood THEN
    VO_Telegram_Msg := 'ВНИМАНИЕ! ПРОТЕЧКА ВОДЫ!';
    VO_Send_Telegram := TRUE;
END_IF;
IF VI_Security_Armed AND NOT L_Prev_Security THEN
    VO_Telegram_Msg := 'ОХРАНА ВКЛЮЧЕНА';
    VO_Send_Telegram := TRUE;
ELSIF NOT VI_Security_Armed AND L_Prev_Security THEN
    VO_Telegram_Msg := 'ОХРАНА ОТКЛЮЧЕНА';
    VO_Send_Telegram := TRUE;
END_IF;

L_Prev_Fire := VI_Fire_Alarm_Active;
L_Prev_Gas := VI_Gas_Alarm_Active;
L_Prev_Flood := VI_Flood_Alarm_Active;
L_Prev_Security := VI_Security_Armed;

// Обновление данных Modbus (раз в 1 сек)
IF (VI_System_Time_MS - L_last_update_time) >= GVL_CONSTANTS.C_MS_IN_SECOND THEN
    L_last_update_time := VI_System_Time_MS;

    // 0: Статус ПЛК и Аварии
    L_tmp_word := 0;
    IF VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE THEN L_tmp_word := L_tmp_word OR 1; END_IF;
    IF VI_Security_Armed THEN L_tmp_word := L_tmp_word OR 2; END_IF;
    IF VI_Flood_Alarm_Active THEN L_tmp_word := L_tmp_word OR 4; END_IF;
    IF VI_Gas_Alarm_Active THEN L_tmp_word := L_tmp_word OR 8; END_IF;
    IF VI_Fire_Alarm_Active THEN L_tmp_word := L_tmp_word OR 16; END_IF;
    VO_Modbus_Registers[0] := L_tmp_word;

    // 1-16: Температуры пола (x10)
    FOR L_i := 1 TO 8 DO
        VO_Modbus_Registers[L_i] := TO_WORD(TO_INT(VI_FloorHeating_Temps[L_i] * 10.0));
    END_FOR;

    // 17-310102: Температуры помещений (x10)
    FOR L_i := 1 TO 16 DO
        VO_Modbus_Registers[16 + L_i] := TO_WORD(TO_INT(VI_Room_Temps[L_i] * 10.0));
    END_FOR;

    // 310103: Состояние клапанов зон (битовая маска 1-16)
    L_tmp_word := 0;
    FOR L_i := 1 TO 8 DO
        IF VI_Zone_Valve_States[L_i] THEN
            L_tmp_word := L_tmp_word OR SHL(TO_WORD(1), L_i - 1);
        END_IF;
    END_FOR;
    VO_Modbus_Registers[33] := L_tmp_word;

    // 34-38: Давление в коллекторах (x100)
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_MANIFOLDS DO
        VO_Modbus_Registers[33 + L_i] := TO_WORD(TO_INT(VI_Manifold_Pressures[L_i] * 100.0));
    END_FOR;

    // 40-55: Базовое освещение
    FOR L_i := 1 TO 32 DO
        VO_Modbus_Registers[39 + L_i] := TO_WORD(VI_Lighting_Base_Levels[L_i]);
    END_FOR;

    // 60-79: Положение штор (20 шт)
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_BLINDS DO
        VO_Modbus_Registers[59 + L_i] := TO_WORD(VI_Blinds_Positions[L_i]);
    END_FOR;

    // 80-82: Розетки (битовая маска, 36 розеток -> 3 WORD)
    FOR L_i := 0 TO (GVL_CONSTANTS.C_MAX_SOCKETS - 1) / 16 DO
        L_tmp_word := 0;
        FOR L_j := 1 TO 16 DO
            L_idx := (L_i * 16) + L_j;
            IF L_idx <= GVL_CONSTANTS.C_MAX_SOCKETS THEN
                IF VI_Socket_States[L_idx] THEN
                    L_tmp_word := L_tmp_word OR SHL(TO_WORD(1), L_j - 1);
                END_IF;
            END_IF;
        END_FOR;
        VO_Modbus_Registers[79 + L_i] := L_tmp_word;
    END_FOR;

    // 100-102: 2FA Request and Code
    VO_Modbus_Registers[100] := SEL(VI_Send_2FA_Req, 0, 1);
    IF VI_Send_2FA_Req THEN
        L_Code_UDINT := STRING_TO_UDINT(VI_2FA_Code);
        VO_Modbus_Registers[101] := TO_WORD(L_Code_UDINT AND 16#FFFF);
        VO_Modbus_Registers[102] := TO_WORD(SHR(L_Code_UDINT, 16));
    ELSE
        VO_Modbus_Registers[101] := 0;
        VO_Modbus_Registers[102] := 0;
    END_IF;

    VO_Data_Ready := TRUE;
END_IF;

// Обработка входящих команд
VO_Arm_Req := FALSE;
VO_Disarm_Req := FALSE;
VO_Set_Scenario_Req := FALSE;
VO_Set_Temp_Req := FALSE;
VO_Set_Vent_Req := FALSE;
VO_Reset_Errors_Req := FALSE;
VO_Set_Config_Req := FALSE;
VO_Sync_Time_Req := FALSE;
L_Has_Command_To_Process := FALSE;

// 1. Прием команды и буферизация
IF VI_Command_Received THEN
    IF VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE THEN
        // Если активен, обрабатываем сразу
        L_Process_Command := VI_Incoming_Command;
        L_Has_Command_To_Process := TRUE;
    ELSE
        // Если резервный, добавляем в буфер
        IF L_Buffer_Count < GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN
            L_Command_Buffer[L_Buffer_Head] := VI_Incoming_Command;
            L_Buffer_Head := L_Buffer_Head + 1;
            IF L_Buffer_Head > GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN L_Buffer_Head := 1; END_IF;
            L_Buffer_Count := L_Buffer_Count + 1;
        END_IF;
    END_IF;
END_IF;

// 2. Извлечение из буфера при переходе в активный режим
IF NOT L_Has_Command_To_Process AND (VI_Local_PLC_Role = E_PLC_ROLE.ROLE_ACTIVE) AND (L_Buffer_Count > 0) THEN
    L_Process_Command := L_Command_Buffer[L_Buffer_Tail];
    L_Buffer_Tail := L_Buffer_Tail + 1;
    IF L_Buffer_Tail > GVL_CONSTANTS.C_MAX_GATEWAY_COMMANDS THEN L_Buffer_Tail := 1; END_IF;
    L_Buffer_Count := L_Buffer_Count - 1;
    L_Has_Command_To_Process := TRUE;
END_IF;

// 3. Обработка команды
IF L_Has_Command_To_Process THEN
    // Проверка IP-адреса источника
    L_IP_Allowed := FALSE;
    IF L_Process_Command.source_ip = '' THEN
        L_IP_Allowed := TRUE; // Если IP не передан, пропускаем (для обратной совместимости или локальных вызовов)
    ELSE
        FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ALLOWED_IPS DO
            IF VI_Allowed_IPs[L_i] = L_Process_Command.source_ip THEN
                L_IP_Allowed := TRUE;
                EXIT;
            END_IF;
        END_FOR;
    END_IF;

    IF NOT L_IP_Allowed THEN
        VO_HMI_Status_Message := 'Gateway: Ошибка безопасности (Неизвестный IP)';
        RETURN;
    END_IF;

    // Проверка целостности данных (CRC32)
    // Размер данных для расчета CRC: размер структуры минус размер самого поля crc32
    L_Command_Size := SIZEOF(L_Process_Command) - SIZEOF(L_Process_Command.crc32);
    L_Calculated_CRC := L_CRC_Calc.Calculate();

    IF L_Calculated_CRC = L_Process_Command.crc32 THEN
        L_Deduplicator(
            VI_Command_ID := L_Process_Command.command_id,
            VI_Command_Type := L_Process_Command.command_type,
            VI_Command_Value := L_Process_Command.target_value,
            VI_System_Time_MS := VI_System_Time_MS
        );

        IF L_Deduplicator.VO_Is_New_Command THEN
            CASE L_Process_Command.command_type OF
        E_Gateway_Command_Type.CMD_SET_SCENARIO: // Управление сценариями
            VO_Set_Scenario_Req := TRUE;
            VO_Target_Scenario := L_Process_Command.target_scenario;
            VO_HMI_Status_Message := 'Gateway: Сценарий изменен';
        E_Gateway_Command_Type.CMD_SET_LIGHT: // Управление освещением
            IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= 32) THEN
                VO_Lighting_Override[L_Process_Command.target_zone] := TO_BYTE(L_Process_Command.target_value);
                VO_HMI_Status_Message := 'Gateway: Команда освещения принята';
            END_IF;
        E_Gateway_Command_Type.CMD_SET_BLINDS: // Управление шторами
            IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_BLINDS) THEN
                VO_Blinds_Override[L_Process_Command.target_zone] := TO_BYTE(L_Process_Command.target_value);
                VO_HMI_Status_Message := 'Gateway: Команда штор принята';
            END_IF;
        E_Gateway_Command_Type.CMD_SET_SOCKET: // Розетки
            IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= GVL_CONSTANTS.C_MAX_SOCKETS) THEN
                VO_Socket_Override[L_Process_Command.target_zone] := L_Process_Command.target_on_off;
                VO_HMI_Status_Message := 'Gateway: Команда розетки принята';
            END_IF;
        E_Gateway_Command_Type.CMD_SET_SECURITY: // Охрана
            IF L_Process_Command.target_armed THEN
                VO_Arm_Req := TRUE;
            ELSE
                VO_Disarm_Req := TRUE;
            END_IF;
            VO_PIN_Code := L_Process_Command.target_pin;
            VO_2FA_Code_In := L_Process_Command.target_2fa_code;
            VO_HMI_Status_Message := 'Gateway: Запрос охраны принят';
        E_Gateway_Command_Type.CMD_SET_TEMP: // Управление температурой
            IF (L_Process_Command.target_zone >= 1) AND (L_Process_Command.target_zone <= 32) THEN
                VO_Set_Temp_Req := TRUE;
                VO_Target_Zone := L_Process_Command.target_zone;
                VO_Target_Temp := L_Process_Command.target_value;
                VO_HMI_Status_Message := 'Gateway: Уставка температуры изменена';
            END_IF;
        E_Gateway_Command_Type.CMD_SET_VENT: // Управление вентиляцией
            // Пример: изменение скорости притока
            VO_Set_Vent_Req := TRUE;
            VO_Target_Vent_Speed := TO_BYTE(L_Process_Command.target_value);
            VO_HMI_Status_Message := 'Gateway: Уставка вентиляции изменена';
        E_Gateway_Command_Type.CMD_TELEGRAM_MSG: // Отправка сообщения в Telegram
            VO_Telegram_Msg := L_Process_Command.telegram_msg;
            VO_Send_Telegram := TRUE;
            VO_HMI_Status_Message := 'Gateway: Сообщение Telegram отправлено';

        E_Gateway_Command_Type.CMD_SYNC_TIME: // Синхронизация времени
            VO_Sync_Time_Req := TRUE;
            VO_New_Time_MS := TO_UDINT(L_Process_Command.target_value);
            VO_HMI_Status_Message := 'Gateway: Время синхронизировано';

        E_Gateway_Command_Type.CMD_RESET_ERRORS: // Квитирование / сброс ошибок
            VO_Reset_Errors_Req := TRUE;
            VO_HMI_Status_Message := 'Gateway: Запрос на сброс ошибок принят';

        E_Gateway_Command_Type.CMD_SET_CONFIG: // Применение конфигурации
            VO_Set_Config_Req := TRUE;
            VO_HMI_Status_Message := 'Gateway: Запрос на применение конфигурации принят';
        END_CASE;
    END_IF;
ELSE
    VO_HMI_Status_Message := 'Gateway: Ошибка CRC команды';
END_IF;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_Gateway_Interface <<<

VO_Code_Valid := FALSE;

// Вычисляем хэш введенного кода
IF LEN(VI_Code_To_Check) > 0 THEN
    pCode := ADR(VI_Code_To_Check);
    L_Input_Hash := 0;
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ACCESS_CODES DO
        IF VI_Access_Codes[L_i] <> 0 AND VI_Access_Codes[L_i] = L_Input_Hash THEN
            VO_Code_Valid := TRUE;
            RETURN;
        END_IF;
    END_FOR;
END_IF;

// Проверяем RFID метку
IF LEN(VI_RFID_To_Check) > 0 THEN
    FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_ACCESS_CODES DO
        IF VI_RFID_Tags[L_i] <> '' AND VI_RFID_Tags[L_i] = VI_RFID_To_Check THEN
            VO_Code_Valid := TRUE;
            RETURN;
        END_IF;
    END_FOR;
END_IF;
// >>> BULK_SYNC_ANCHOR: FB_AccessCode_Manager <<<

// >>> SYNC_TEST_MARKER_002 <<<


L_Current_TOD := GVL_STATUS.G_Current_TOD;
VO_Current_TOD := L_Current_TOD;

// Equation of Time (EoT) in minutes
L_B := 360.0 / 365.0 * TO_REAL(VI_Day_Of_Year - 81) * L_Rad;
L_EoT := 9.87 * SIN(2.0 * L_B) - 7.53 * COS(L_B) - 1.5 * SIN(L_B);

// Solar Declination in degrees
L_Declination := 23.45 * SIN(360.0 / 365.0 * TO_REAL(VI_Day_Of_Year + 284) * L_Rad);

// Hour angle
L_Cos_Omega := -TAN(VI_Latitude * L_Rad) * TAN(L_Declination * L_Rad);

IF L_Cos_Omega > 1.0 THEN
    L_Cos_Omega := 1.0; // Polar night
ELSIF L_Cos_Omega < -1.0 THEN
    L_Cos_Omega := -1.0; // Polar day
END_IF;

L_Omega := ACOS(L_Cos_Omega) * L_Deg;

// Sunrise and Sunset in local time (hours)
L_Sunrise_Local := 12.0 - (L_Omega / 15.0) - (L_EoT / 60.0) + (VI_Timezone * 15.0 - VI_Longitude) / 15.0;
L_Sunset_Local := 12.0 + (L_Omega / 15.0) - (L_EoT / 60.0) + (VI_Timezone * 15.0 - VI_Longitude) / 15.0;

// Handle bounds
IF L_Sunrise_Local < 0.0 THEN L_Sunrise_Local := L_Sunrise_Local + 24.0; END_IF;
IF L_Sunrise_Local >= 24.0 THEN L_Sunrise_Local := L_Sunrise_Local - 24.0; END_IF;
IF L_Sunset_Local < 0.0 THEN L_Sunset_Local := L_Sunset_Local + 24.0; END_IF;
IF L_Sunset_Local >= 24.0 THEN L_Sunset_Local := L_Sunset_Local - 24.0; END_IF;

// Конвертация в TOD
VO_Sunrise_Time := TO_TOD(TO_UDINT(L_Sunrise_Local * 3600000.0));
VO_Sunset_Time := TO_TOD(TO_UDINT(L_Sunset_Local * 3600000.0));

// ТЗ 15.2: Закат + 30 мин / Рассвет - 30 мин
VO_Is_Night := (L_Current_TOD > (VO_Sunset_Time + T#30m)) OR (L_Current_TOD < (VO_Sunrise_Time - T#30m));
// >>> SYNC_TEST_MARKER_FORCE <<<
// >>> BULK_SYNC_ANCHOR: FB_Astro_Timer <<<

VO_Freeze_Alert := FALSE;
VO_Pump_Force_On := FALSE;

FOR L_i := 1 TO GVL_CONSTANTS.C_MAX_HEATING_CIRCUITS DO
    IF VI_Floor_Temps[L_i] < VI_Threshold THEN
        VO_Freeze_Alert := TRUE;
        VO_Pump_Force_On := TRUE;
        RETURN;
    END_IF;
END_FOR;

IF VI_Outdoor_Temp < -5.0 THEN
    VO_Pump_Force_On := TRUE;
END_IF;

// ============================================================
// SCENARIO POLICY OWNER
// ============================================================

// 1. Base priority resolution
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_SAFE_STOP THEN
    GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
    GVL_POLICY.G_Scenario_Source := SRC_SAFETY;

ELSIF GVL_POLICY.G_Scenario_Request_Operator <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Operator;
    GVL_POLICY.G_Scenario_Source := SRC_OPERATOR;

ELSIF GVL_POLICY.G_Scenario_Request_Gateway <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Gateway;
    GVL_POLICY.G_Scenario_Source := SRC_GATEWAY;

ELSIF GVL_POLICY.G_Scenario_Request_Rule <> E_SCENARIO_TYPE.SCENARIO_NONE THEN
    GVL_POLICY.G_Scenario_Intent := GVL_POLICY.G_Scenario_Request_Rule;
    GVL_POLICY.G_Scenario_Source := SRC_RULE;

ELSE
    GVL_POLICY.G_Scenario_Intent := GVL_STATUS.G_Current_Scenario;
    GVL_POLICY.G_Scenario_Source := SRC_NONE;
END_IF;

// 2. Fail-safe clamp
CASE GVL_STATE.G_System_Mode OF
    E_System_Operating_Mode.MODE_SAFE_STOP:
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        GVL_POLICY.G_Scenario_Source := SRC_SAFETY;

    E_System_Operating_Mode.MODE_FREEZE_PROTECTION:
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
        GVL_POLICY.G_Scenario_Source := SRC_POLICY;

    E_System_Operating_Mode.MODE_DEGRADED:
        CASE GVL_POLICY.G_Scenario_Intent OF
            E_SCENARIO_TYPE.SCENARIO_NONE,
            E_SCENARIO_TYPE.SCENARIO_PRESENCE,
            E_SCENARIO_TYPE.SCENARIO_AWAY,
            E_SCENARIO_TYPE.SCENARIO_SLEEP:
                ;
        ELSE
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_NONE;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;
        END_CASE;
END_CASE;

// 3. Context automation
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_NORMAL THEN
    IF GVL_ALARM.G_Security_Armed AND
       (GVL_POLICY.G_Scenario_Request_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Intent <> E_SCENARIO_TYPE.SCENARIO_AWAY) THEN
        GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
        GVL_POLICY.G_Scenario_Source := SRC_POLICY;
    END_IF;
END_IF;

// 4. Degraded adaptation
IF GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_DEGRADED THEN
    IF (GVL_POLICY.G_Scenario_Request_Operator = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Gateway = E_SCENARIO_TYPE.SCENARIO_NONE) AND
       (GVL_POLICY.G_Scenario_Request_Rule = E_SCENARIO_TYPE.SCENARIO_NONE) THEN

        IF GVL_ALARM.G_Security_Armed THEN
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_AWAY;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;

        ELSIF GVL_POLICY.G_Scenario_Intent = E_SCENARIO_TYPE.SCENARIO_PRESENCE THEN
            GVL_POLICY.G_Scenario_Intent := E_SCENARIO_TYPE.SCENARIO_SLEEP;
            GVL_POLICY.G_Scenario_Source := SRC_POLICY;
        END_IF;
    END_IF;
END_IF;

// 5. Heating bridge
GVL_STATE.G_Preheat_Request := GVL_POLICY.G_Rule_Preheat_Request;
GVL_STATE.G_Freeze_Request :=
    (GVL_STATE.G_System_Mode = E_System_Operating_Mode.MODE_FREEZE_PROTECTION);

// Вызов основной программы
PRG_System();
